  ZI.STAERKER = [
    {"id": "STAERKER:pausenecke","meinung": "Wir sollten eine ruhige Pausenecke einrichten. Ziel: nach der Pause konzentriert lernen.","optionen": [{"text": "… weil wir dort abschalten und neue Kraft sammeln.","ok": true,"info": "Dieser Grund erklärt das Ziel: nach der Pause konzentriert lernen.","warum": [{"text": "Eine ruhige Ecke lässt uns abschalten und neue Kraft sammeln.","ok": true},{"text": "In der Ecke können wir Karten mit unseren Freunden tauschen.","ok": false},{"text": "Die Pausenecke befindet sich auf einem Teil unseres Schulhofs.","ok": false}]},{"text": "… weil wir dort Karten mit Freunden tauschen können.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:hausaufgaben","meinung": "Wir sollten Hausaufgaben am Ende gemeinsam notieren. Ziel: keine Aufgabe beim Aufschreiben übersehen.","optionen": [{"text": "… weil wir die Einträge noch mit der Tafel vergleichen.","ok": true,"info": "Dieser Grund erklärt das Ziel: keine Aufgabe beim Aufschreiben übersehen.","warum": [{"text": "Beim Vergleich mit der Tafel entdecken wir fehlende Aufgaben.","ok": true},{"text": "Beim Notieren können wir unsere Hefte ordentlich gestalten.","ok": false},{"text": "Nach dem Aufschreiben stehen die Aufgaben in unseren Heften.","ok": false}]},{"text": "… weil wir dabei unsere Hefte ordentlich gestalten.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:schulbeginn","meinung": "Wir sollten eine Woche lang später mit der Schule beginnen. Ziel: prüfen, ob wir morgens wacher lernen.","optionen": [{"text": "… weil wir unsere Müdigkeit vor und nach dem Versuch vergleichen.","ok": true,"info": "Dieser Grund erklärt das Ziel: prüfen, ob wir morgens wacher lernen.","warum": [{"text": "Ein Vergleich beider Wochen zeigt, wie müde wir jeweils sind.","ok": true},{"text": "Vor dem späteren Beginn können wir gemeinsam frühstücken.","ok": false},{"text": "Beim späteren Beginn startet der Unterricht zu einer neuen Uhrzeit.","ok": false}]},{"text": "… weil wir morgens gemeinsam in Ruhe frühstücken können.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:sitzordnung","meinung": "Wir sollten einen freien Blick auf die Tafel ermöglichen. Ziel: die Tafel von jedem Platz gut erkennen.","optionen": [{"text": "… weil keiner beim Lesen um andere herumsehen muss.","ok": true,"info": "Dieser Grund erklärt das Ziel: die Tafel von jedem Platz gut erkennen.","warum": [{"text": "Mit freier Sicht müssen wir nicht um andere herumsehen.","ok": true},{"text": "Nach dem Umstellen können wir unsere Freunde leichter sehen.","ok": false},{"text": "Die Tafel hängt an der vorderen Wand unseres Klassenraums.","ok": false}]},{"text": "… weil wir unsere Freunde im Raum leichter sehen können.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:klassenregel","meinung": "Wir sollten eine feste Reihenfolge beim Sprechen nutzen. Ziel: leise Stimmen im Klassenrat besser hören.","optionen": [{"text": "… weil jeder reden kann, ohne von anderen übertönt zu werden.","ok": true,"info": "Dieser Grund erklärt das Ziel: leise Stimmen im Klassenrat besser hören.","warum": [{"text": "In der Reihenfolge übertönen andere keine leisen Stimmen.","ok": true},{"text": "Vor dem Sprechen können wir unsere Beiträge aufschreiben.","ok": false},{"text": "Im Klassenrat sprechen mehrere Kinder nacheinander über ein Thema.","ok": false}]},{"text": "… weil wir unsere Beiträge dabei vorher aufschreiben können.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:dienste","meinung": "Wir sollten die Klassendienste jede Woche wechseln. Ziel: die Arbeit in der Klasse fair verteilen.","optionen": [{"text": "… weil nicht jede Woche dieselben Kinder alles erledigen.","ok": true,"info": "Dieser Grund erklärt das Ziel: die Arbeit in der Klasse fair verteilen.","warum": [{"text": "Beim Wechsel erledigen nicht immer dieselben Kinder die Arbeit.","ok": true},{"text": "Durch den Wechsel lernen wir unterschiedliche Dienste kennen.","ok": false},{"text": "Auf dem Dienstplan stehen in jeder Woche andere Kindernamen.","ok": false}]},{"text": "… weil wir verschiedene Aufgaben im Klassenraum kennenlernen.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:klassenfahrt","meinung": "Wir sollten bei der Klassenfahrt gemeinsame Aufgaben planen. Ziel: uns als Klasse besser kennenlernen.","optionen": [{"text": "… weil wir beim Lösen einer Aufgabe aufeinander angewiesen sind.","ok": true,"info": "Dieser Grund erklärt das Ziel: uns als Klasse besser kennenlernen.","warum": [{"text": "Bei gemeinsamen Aufgaben sind wir aufeinander angewiesen.","ok": true},{"text": "Auf der Fahrt können wir die Wege um die Unterkunft erkunden.","ok": false},{"text": "Eine Klassenfahrt dauert meist mehrere aufeinanderfolgende Tage.","ok": false}]},{"text": "… weil wir dabei die Wege rund um die Unterkunft erkunden.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:schulhof","meinung": "Wir sollten Spielgeräte in der Pause ausleihen können. Ziel: mehr Kindern verschiedene Spiele ermöglichen.","optionen": [{"text": "… weil auch Kinder ohne eigenes Gerät etwas ausprobieren können.","ok": true,"info": "Dieser Grund erklärt das Ziel: mehr Kindern verschiedene Spiele ermöglichen.","warum": [{"text": "Die Ausleihe ermöglicht Spiele auch ohne eigene Geräte.","ok": true},{"text": "Bei der Ausgabe lernen wir die Namen anderer Kinder kennen.","ok": false},{"text": "Die ausgeliehenen Geräte werden am Ende der Pause zurückgegeben.","ok": false}]},{"text": "… weil wir beim Ausleihen die Namen der anderen besser lernen.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:sport","meinung": "Wir sollten im Sport verschiedene Spielarten ausprobieren. Ziel: unterschiedliche Stärken der Kinder entdecken.","optionen": [{"text": "… weil nicht in jedem Spiel dieselben Fähigkeiten zählen.","ok": true,"info": "Dieser Grund erklärt das Ziel: unterschiedliche Stärken der Kinder entdecken.","warum": [{"text": "Bei verschiedenen Spielen zählen unterschiedliche Fähigkeiten.","ok": true},{"text": "Durch neue Spiele lernen wir verschiedene Spielnamen kennen.","ok": false},{"text": "Zu verschiedenen Spielen gehören eigene Regeln und Materialien.","ok": false}]},{"text": "… weil wir dabei die Namen vieler neuer Spiele kennenlernen.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:ags","meinung": "Wir sollten vor der AG-Wahl Schnupperstunden anbieten. Ziel: eine passende AG auswählen.","optionen": [{"text": "… weil wir vor der Wahl die Tätigkeit selbst ausprobieren.","ok": true,"info": "Dieser Grund erklärt das Ziel: eine passende AG auswählen.","warum": [{"text": "Beim Schnuppern können wir die Tätigkeit vor der Wahl testen.","ok": true},{"text": "Beim Schnuppern lernen wir Kinder aus anderen Klassen kennen.","ok": false},{"text": "Die AGs finden jede Woche nach dem normalen Unterricht statt.","ok": false}]},{"text": "… weil wir dabei Kinder aus anderen Klassen kennenlernen.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:handys","meinung": "Wir sollten Handys während der Gruppenarbeit weglegen. Ziel: in der Gruppe aufmerksam zusammenarbeiten.","optionen": [{"text": "… weil keine Nachricht mitten im Gespräch unsere Aufmerksamkeit ablenkt.","ok": true,"info": "Dieser Grund erklärt das Ziel: in der Gruppe aufmerksam zusammenarbeiten.","warum": [{"text": "Ohne Nachrichten werden wir im Gespräch seltener abgelenkt.","ok": true},{"text": "In der Tasche können die Geräte nicht vom Gruppentisch fallen.","ok": false},{"text": "Während der Gruppenarbeit liegen die Handys in unseren Taschen.","ok": false}]},{"text": "… weil wir die Geräte dann nicht aus Versehen fallen lassen.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:haustiere","meinung": "Wir sollten vor dem Tierkauf einen Pflegeplan machen. Ziel: die tägliche Versorgung des Tieres sichern.","optionen": [{"text": "… weil wir vorher klären, wer jeden Tag welche Aufgabe übernimmt.","ok": true,"info": "Dieser Grund erklärt das Ziel: die tägliche Versorgung des Tieres sichern.","warum": [{"text": "Der Plan klärt für jeden Tag die Zuständigkeit bei der Pflege.","ok": true},{"text": "Beim Planen können wir uns einen Namen für das Tier überlegen.","ok": false},{"text": "In einem Pflegeplan stehen mehrere Aufgaben und Kindernamen.","ok": false}]},{"text": "… weil wir dabei überlegen, welchen Namen das Tier bekommt.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:freizeit","meinung": "Wir sollten einen Nachmittag ohne feste Termine lassen. Ziel: Zeit für eigene Ideen finden.","optionen": [{"text": "… weil wir selbst entscheiden können, was wir beginnen möchten.","ok": true,"info": "Dieser Grund erklärt das Ziel: Zeit für eigene Ideen finden.","warum": [{"text": "In freier Zeit können wir selbst ein eigenes Vorhaben beginnen.","ok": true},{"text": "Für einen freien Nachmittag brauchen wir keine Kurstasche.","ok": false},{"text": "Ein freier Nachmittag hat keinen festen Platz im Kursplan.","ok": false}]},{"text": "… weil wir dann keine Sporttasche für einen Kurs packen müssen.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:fahrrad","meinung": "Wir sollten Fahrräder vor dem Ausflug gemeinsam prüfen. Ziel: mit sicheren Fahrrädern losfahren.","optionen": [{"text": "… weil wir defekte Bremsen noch vor der Abfahrt entdecken.","ok": true,"info": "Dieser Grund erklärt das Ziel: mit sicheren Fahrrädern losfahren.","warum": [{"text": "Beim Test fallen kaputte Bremsen schon vor der Abfahrt auf.","ok": true},{"text": "Beim Treffen können wir die Fahrräder der anderen ansehen.","ok": false},{"text": "Vor dem Ausflug stehen viele Fahrräder auf unserem Schulhof.","ok": false}]},{"text": "… weil wir dabei die verschiedenen Fahrräder der Klasse ansehen.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:schulweg","meinung": "Wir sollten für den Schulweg sichere Querungen auswählen. Ziel: gefahrlos über viel befahrene Straßen kommen.","optionen": [{"text": "… weil wir an übersichtlichen Stellen den Verkehr besser sehen.","ok": true,"info": "Dieser Grund erklärt das Ziel: gefahrlos über viel befahrene Straßen kommen.","warum": [{"text": "An freien Querungen können wir den Verkehr besser sehen.","ok": true},{"text": "Auf dem gewählten Schulweg treffen wir andere Kinder häufiger.","ok": false},{"text": "Auf unserem Schulweg müssen wir mehrere Straßen überqueren.","ok": false}]},{"text": "… weil wir auf diesem Weg andere Kinder öfter treffen.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:umwelt","meinung": "Wir sollten in leeren Klassenräumen das Licht ausschalten. Ziel: unnötigen Stromverbrauch vermeiden.","optionen": [{"text": "… weil leere Räume keine Beleuchtung zum Arbeiten brauchen.","ok": true,"info": "Dieser Grund erklärt das Ziel: unnötigen Stromverbrauch vermeiden.","warum": [{"text": "Ohne Menschen im Raum ist keine Beleuchtung zum Arbeiten nötig.","ok": true},{"text": "Das Ausschalten erinnert uns an das Ende der Arbeitsphase.","ok": false},{"text": "An der Decke unserer Klassenräume hängen mehrere Lampen.","ok": false}]},{"text": "… weil wir dadurch an das Ende der Pause erinnert werden.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:muell","meinung": "Wir sollten Papier getrennt von Essensresten sammeln. Ziel: sauberes Papier wiederverwerten lassen.","optionen": [{"text": "… weil Essensreste das gesammelte Papier nicht verschmutzen.","ok": true,"info": "Dieser Grund erklärt das Ziel: sauberes Papier wiederverwerten lassen.","warum": [{"text": "Ohne Essensreste wird das gesammelte Papier nicht schmutzig.","ok": true},{"text": "Beim Trennen lernen wir unsere verschiedenen Abfalleimer kennen.","ok": false},{"text": "Papier und Essensreste gehören in unterschiedliche Abfalleimer.","ok": false}]},{"text": "… weil wir dadurch unsere verschiedenen Abfalleimer kennenlernen.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:ausflug","meinung": "Wir sollten Ausflugsziele mit dem Bus erreichen können. Ziel: allen Kindern die Teilnahme ermöglichen.","optionen": [{"text": "… weil niemand für die Anfahrt ein eigenes Auto braucht.","ok": true,"info": "Dieser Grund erklärt das Ziel: allen Kindern die Teilnahme ermöglichen.","warum": [{"text": "Im Bus kann man auch ohne eigenes Auto zum Ziel mitkommen.","ok": true},{"text": "Bei der Busfahrt können wir die Landschaft unterwegs ansehen.","ok": false},{"text": "Der Bus fährt an einer Haltestelle vor unserer Schule ab.","ok": false}]},{"text": "… weil wir während der Fahrt die Landschaft anschauen können.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:klassenfest","meinung": "Wir sollten für das Klassenfest verschiedene Aufgaben anbieten. Ziel: jedem Kind eine passende Beteiligung ermöglichen.","optionen": [{"text": "… weil auch Kinder ohne Bühnenmut einen Beitrag leisten können.","ok": true,"info": "Dieser Grund erklärt das Ziel: jedem Kind eine passende Beteiligung ermöglichen.","warum": [{"text": "Auch ohne Bühnenmut können Kinder einen Beitrag leisten.","ok": true},{"text": "Bei verschiedenen Aufgaben sammeln wir mehr Ideen für das Fest.","ok": false},{"text": "Beim Klassenfest müssen mehrere Aufgaben gleichzeitig erledigt werden.","ok": false}]},{"text": "… weil wir dadurch mehr verschiedene Dinge für das Fest sammeln.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:gruppenarbeit","meinung": "Wir sollten in Gruppen klare Aufgaben absprechen. Ziel: doppelte Arbeit und vergessene Teile vermeiden.","optionen": [{"text": "… weil jeder weiß, welchen Teil der Aufgabe er übernimmt.","ok": true,"info": "Dieser Grund erklärt das Ziel: doppelte Arbeit und vergessene Teile vermeiden.","warum": [{"text": "Durch Absprachen kennt jeder seinen eigenen Teil der Aufgabe.","ok": true},{"text": "Bei der Absprache können wir mit neuen Partnern sprechen.","ok": false},{"text": "In einer Arbeitsgruppe sitzen mehrere Kinder an einem Tisch.","ok": false}]},{"text": "… weil wir dadurch öfter mit neuen Partnern sprechen können.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:bibliothek","meinung": "Wir sollten Bücher in der Klassenbibliothek beschriften. Ziel: passende Bücher schneller finden.","optionen": [{"text": "… weil wir am Schild sofort das Thema eines Regals erkennen.","ok": true,"info": "Dieser Grund erklärt das Ziel: passende Bücher schneller finden.","warum": [{"text": "Die Schilder zeigen sofort, welches Thema ein Regal enthält.","ok": true},{"text": "Mit selbst gemalten Schildern können wir Bilder im Raum zeigen.","ok": false},{"text": "Die Bücher unserer Klassenbibliothek stehen in mehreren Regalen.","ok": false}]},{"text": "… weil wir unsere selbst gemalten Schilder im Raum zeigen können.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:schulessen","meinung": "Wir sollten beim Schulessen kleine erste Portionen wählen. Ziel: weniger gutes Essen wegwerfen.","optionen": [{"text": "… weil wir erst nachnehmen, wenn wir noch Hunger haben.","ok": true,"info": "Dieser Grund erklärt das Ziel: weniger gutes Essen wegwerfen.","warum": [{"text": "Beim Nachnehmen passt die Essensmenge besser zum Hunger.","ok": true},{"text": "Mit kleinen Portionen können wir verschiedene Teller erproben.","ok": false},{"text": "An der Ausgabe stehen für die Kinder mehrere Stapel Teller bereit.","ok": false}]},{"text": "… weil wir dadurch verschiedene Tellergrößen ausprobieren können.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:trinken","meinung": "Wir sollten Wasserflaschen im Klassenraum auffüllen können. Ziel: beim Lernen genug Wasser trinken.","optionen": [{"text": "… weil leere Flaschen auch während des Schultags wieder gefüllt werden.","ok": true,"info": "Dieser Grund erklärt das Ziel: beim Lernen genug Wasser trinken.","warum": [{"text": "An der Füllstelle werden leere Flaschen wieder gefüllt.","ok": true},{"text": "Mit eigenen Flaschen müssen wir keine fremden Becher benutzen.","ok": false},{"text": "Unsere Trinkflaschen haben verschiedene Größen und Farben.","ok": false}]},{"text": "… weil wir unsere Flaschen nicht mit anderen verwechseln müssen.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:lesezeit","meinung": "Wir sollten eine kurze stille Lesezeit einführen. Ziel: ohne Unterbrechung in Geschichten eintauchen.","optionen": [{"text": "… weil alle gleichzeitig lesen und niemand dazwischen spricht.","ok": true,"info": "Dieser Grund erklärt das Ziel: ohne Unterbrechung in Geschichten eintauchen.","warum": [{"text": "Wenn alle still lesen, spricht niemand in die Geschichte hinein.","ok": true},{"text": "In der Lesezeit können wir unsere Lieblingsbücher zeigen.","ok": false},{"text": "In der Lesezeit liegen viele Bücher auf den Tischen im Raum.","ok": false}]},{"text": "… weil wir dabei unsere mitgebrachten Lieblingsbücher zeigen können.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:partnerwahl","meinung": "Wir sollten bei kurzen Partneraufgaben gelegentlich auslosen. Ziel: mit verschiedenen Kindern zusammenarbeiten lernen.","optionen": [{"text": "… weil wir auch mit Kindern außerhalb des Freundeskreises üben.","ok": true,"info": "Dieser Grund erklärt das Ziel: mit verschiedenen Kindern zusammenarbeiten lernen.","warum": [{"text": "Durch Lose üben wir auch mit Kindern außerhalb unserer Freunde.","ok": true},{"text": "Beim Losen können wir unsere eigenen Namenskärtchen nutzen.","ok": false},{"text": "Bei einer Partneraufgabe arbeiten jeweils zwei Kinder zusammen.","ok": false}]},{"text": "… weil wir durch das Losen unsere Namenskärtchen nutzen können.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:ordnung","meinung": "Wir sollten gemeinsam benutztes Material fest einsortieren. Ziel: benötigte Sachen ohne langes Suchen finden.","optionen": [{"text": "… weil jeder den gleichen Platz für Schere und Kleber kennt.","ok": true,"info": "Dieser Grund erklärt das Ziel: benötigte Sachen ohne langes Suchen finden.","warum": [{"text": "Ein fester Platz zeigt allen, wo Schere und Kleber liegen.","ok": true},{"text": "Beim Einsortieren können wir unsere Materialkisten bemalen.","ok": false},{"text": "Scheren und Kleber gehören gemeinsam zu unserem Bastelmaterial.","ok": false}]},{"text": "… weil wir dabei unsere Materialkisten neu bemalen können.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:spielregeln","meinung": "Wir sollten Spielregeln vor dem Turnier gemeinsam klären. Ziel: Streit über unklare Entscheidungen vermeiden.","optionen": [{"text": "… weil wir schon vor dem Spiel wissen, welche Regeln gelten.","ok": true,"info": "Dieser Grund erklärt das Ziel: Streit über unklare Entscheidungen vermeiden.","warum": [{"text": "Nach dem Klären wissen beide Teams, welche Regeln gelten.","ok": true},{"text": "Vor dem Turnier erfahren wir die Namen der Mannschaften.","ok": false},{"text": "Bei einem Turnier spielen mehrere Mannschaften gegeneinander.","ok": false}]},{"text": "… weil wir dabei die Namen der anderen Mannschaften erfahren.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:radstaender","meinung": "Wir sollten Fahrräder an festen Plätzen abstellen. Ziel: den Eingang zur Schule frei halten.","optionen": [{"text": "… weil kein Rad mitten im Weg vor der Eingangstür steht.","ok": true,"info": "Dieser Grund erklärt das Ziel: den Eingang zur Schule frei halten.","warum": [{"text": "Mit festen Plätzen steht kein Rad vor unserer Eingangstür.","ok": true},{"text": "Bei festen Plätzen finden wir die Räder unserer Freunde leichter.","ok": false},{"text": "Die Fahrradständer unserer Schule stehen neben dem Eingang.","ok": false}]},{"text": "… weil wir dort die Fahrräder unserer Freunde wiederfinden können.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:tauschregal","meinung": "Wir sollten ein Tauschregal für brauchbare Schulsachen aufstellen. Ziel: gut erhaltene Dinge länger nutzen.","optionen": [{"text": "… weil andere Kinder noch verwendbare Sachen weiterbenutzen können.","ok": true,"info": "Dieser Grund erklärt das Ziel: gut erhaltene Dinge länger nutzen.","warum": [{"text": "Im Regal können andere die noch guten Sachen weiterbenutzen.","ok": true},{"text": "Beim Tauschen entdecken wir verschiedene Farben und Muster.","ok": false},{"text": "In einem Tauschregal liegen verschiedene Sachen zum Mitnehmen.","ok": false}]},{"text": "… weil wir dabei verschiedene Farben und Muster entdecken.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]},
    {"id": "STAERKER:lernpause","meinung": "Wir sollten bei langen Arbeitsphasen kurze Bewegungspausen machen. Ziel: nach langem Sitzen wieder aufmerksam arbeiten.","optionen": [{"text": "… weil wir die sitzende Haltung kurz unterbrechen können.","ok": true,"info": "Dieser Grund erklärt das Ziel: nach langem Sitzen wieder aufmerksam arbeiten.","warum": [{"text": "In Bewegungspausen unterbrechen wir das lange Sitzen.","ok": true},{"text": "In der Pause können wir unsere gewählten Bewegungen zeigen.","ok": false},{"text": "Eine Bewegungspause unterbricht unsere lange Arbeitsphase.","ok": false}]},{"text": "… weil wir dabei unsere selbst gewählten Bewegungen zeigen können.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."}]}
  ];
  /* Tiefe 3: Eine schwache Begründung besser machen */
  ZI.VERBESSERN = [
    {"id": "VERBESSERN:pausenecke","schwach": "Wir sollten eine ruhige Pausenecke einrichten. Das finde ich einfach passend. Ziel: nach der Pause konzentriert lernen.","optionen": [{"text": "… weil wir dort abschalten und neue Kraft sammeln.","ok": true,"info": "Dieser Grund erklärt das Ziel: nach der Pause konzentriert lernen.","warum": [{"text": "Eine ruhige Ecke lässt uns abschalten und neue Kraft sammeln.","ok": true},{"text": "In der Ecke können wir Karten mit unseren Freunden tauschen.","ok": false},{"text": "Die Pausenecke befindet sich auf einem Teil unseres Schulhofs.","ok": false}]},{"text": "… weil wir dort Karten mit Freunden tauschen können.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil eine Pausenecke ein Teil unseres Schulhofs ist.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:hausaufgaben","schwach": "Wir sollten Hausaufgaben am Ende gemeinsam notieren. Das finde ich einfach passend. Ziel: keine Aufgabe beim Aufschreiben übersehen.","optionen": [{"text": "… weil wir die Einträge noch mit der Tafel vergleichen.","ok": true,"info": "Dieser Grund erklärt das Ziel: keine Aufgabe beim Aufschreiben übersehen.","warum": [{"text": "Beim Vergleich mit der Tafel entdecken wir fehlende Aufgaben.","ok": true},{"text": "Beim Notieren können wir unsere Hefte ordentlich gestalten.","ok": false},{"text": "Nach dem Aufschreiben stehen die Aufgaben in unseren Heften.","ok": false}]},{"text": "… weil wir dabei unsere Hefte ordentlich gestalten.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil die Aufgaben am Ende in unseren Heften stehen.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:schulbeginn","schwach": "Wir sollten eine Woche lang später mit der Schule beginnen. Das finde ich einfach passend. Ziel: prüfen, ob wir morgens wacher lernen.","optionen": [{"text": "… weil wir unsere Müdigkeit vor und nach dem Versuch vergleichen.","ok": true,"info": "Dieser Grund erklärt das Ziel: prüfen, ob wir morgens wacher lernen.","warum": [{"text": "Ein Vergleich beider Wochen zeigt, wie müde wir jeweils sind.","ok": true},{"text": "Vor dem späteren Beginn können wir gemeinsam frühstücken.","ok": false},{"text": "Beim späteren Beginn startet der Unterricht zu einer neuen Uhrzeit.","ok": false}]},{"text": "… weil wir morgens gemeinsam in Ruhe frühstücken können.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil der Unterricht dann zu einer anderen Uhrzeit beginnt.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:sitzordnung","schwach": "Wir sollten einen freien Blick auf die Tafel ermöglichen. Das finde ich einfach passend. Ziel: die Tafel von jedem Platz gut erkennen.","optionen": [{"text": "… weil keiner beim Lesen um andere herumsehen muss.","ok": true,"info": "Dieser Grund erklärt das Ziel: die Tafel von jedem Platz gut erkennen.","warum": [{"text": "Mit freier Sicht müssen wir nicht um andere herumsehen.","ok": true},{"text": "Nach dem Umstellen können wir unsere Freunde leichter sehen.","ok": false},{"text": "Die Tafel hängt an der vorderen Wand unseres Klassenraums.","ok": false}]},{"text": "… weil wir unsere Freunde im Raum leichter sehen können.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil die Tafel vorne an der Wand unseres Raums hängt.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:klassenregel","schwach": "Wir sollten eine feste Reihenfolge beim Sprechen nutzen. Das finde ich einfach passend. Ziel: leise Stimmen im Klassenrat besser hören.","optionen": [{"text": "… weil jeder reden kann, ohne von anderen übertönt zu werden.","ok": true,"info": "Dieser Grund erklärt das Ziel: leise Stimmen im Klassenrat besser hören.","warum": [{"text": "In der Reihenfolge übertönen andere keine leisen Stimmen.","ok": true},{"text": "Vor dem Sprechen können wir unsere Beiträge aufschreiben.","ok": false},{"text": "Im Klassenrat sprechen mehrere Kinder nacheinander über ein Thema.","ok": false}]},{"text": "… weil wir unsere Beiträge dabei vorher aufschreiben können.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil im Klassenrat mehrere Kinder nacheinander sprechen.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:dienste","schwach": "Wir sollten die Klassendienste jede Woche wechseln. Das finde ich einfach passend. Ziel: die Arbeit in der Klasse fair verteilen.","optionen": [{"text": "… weil nicht jede Woche dieselben Kinder alles erledigen.","ok": true,"info": "Dieser Grund erklärt das Ziel: die Arbeit in der Klasse fair verteilen.","warum": [{"text": "Beim Wechsel erledigen nicht immer dieselben Kinder die Arbeit.","ok": true},{"text": "Durch den Wechsel lernen wir unterschiedliche Dienste kennen.","ok": false},{"text": "Auf dem Dienstplan stehen in jeder Woche andere Kindernamen.","ok": false}]},{"text": "… weil wir verschiedene Aufgaben im Klassenraum kennenlernen.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil jede Woche neue Namen auf unserem Dienstplan stehen.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:klassenfahrt","schwach": "Wir sollten bei der Klassenfahrt gemeinsame Aufgaben planen. Das finde ich einfach passend. Ziel: uns als Klasse besser kennenlernen.","optionen": [{"text": "… weil wir beim Lösen einer Aufgabe aufeinander angewiesen sind.","ok": true,"info": "Dieser Grund erklärt das Ziel: uns als Klasse besser kennenlernen.","warum": [{"text": "Bei gemeinsamen Aufgaben sind wir aufeinander angewiesen.","ok": true},{"text": "Auf der Fahrt können wir die Wege um die Unterkunft erkunden.","ok": false},{"text": "Eine Klassenfahrt dauert meist mehrere aufeinanderfolgende Tage.","ok": false}]},{"text": "… weil wir dabei die Wege rund um die Unterkunft erkunden.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil eine Klassenfahrt meist mehrere Tage hintereinander dauert.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:schulhof","schwach": "Wir sollten Spielgeräte in der Pause ausleihen können. Das finde ich einfach passend. Ziel: mehr Kindern verschiedene Spiele ermöglichen.","optionen": [{"text": "… weil auch Kinder ohne eigenes Gerät etwas ausprobieren können.","ok": true,"info": "Dieser Grund erklärt das Ziel: mehr Kindern verschiedene Spiele ermöglichen.","warum": [{"text": "Die Ausleihe ermöglicht Spiele auch ohne eigene Geräte.","ok": true},{"text": "Bei der Ausgabe lernen wir die Namen anderer Kinder kennen.","ok": false},{"text": "Die ausgeliehenen Geräte werden am Ende der Pause zurückgegeben.","ok": false}]},{"text": "… weil wir beim Ausleihen die Namen der anderen besser lernen.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil die ausgeliehenen Geräte am Ende zurückgegeben werden.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:sport","schwach": "Wir sollten im Sport verschiedene Spielarten ausprobieren. Das finde ich einfach passend. Ziel: unterschiedliche Stärken der Kinder entdecken.","optionen": [{"text": "… weil nicht in jedem Spiel dieselben Fähigkeiten zählen.","ok": true,"info": "Dieser Grund erklärt das Ziel: unterschiedliche Stärken der Kinder entdecken.","warum": [{"text": "Bei verschiedenen Spielen zählen unterschiedliche Fähigkeiten.","ok": true},{"text": "Durch neue Spiele lernen wir verschiedene Spielnamen kennen.","ok": false},{"text": "Zu verschiedenen Spielen gehören eigene Regeln und Materialien.","ok": false}]},{"text": "… weil wir dabei die Namen vieler neuer Spiele kennenlernen.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil verschiedene Sportspiele eigene Regeln und Materialien haben.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:ags","schwach": "Wir sollten vor der AG-Wahl Schnupperstunden anbieten. Das finde ich einfach passend. Ziel: eine passende AG auswählen.","optionen": [{"text": "… weil wir vor der Wahl die Tätigkeit selbst ausprobieren.","ok": true,"info": "Dieser Grund erklärt das Ziel: eine passende AG auswählen.","warum": [{"text": "Beim Schnuppern können wir die Tätigkeit vor der Wahl testen.","ok": true},{"text": "Beim Schnuppern lernen wir Kinder aus anderen Klassen kennen.","ok": false},{"text": "Die AGs finden jede Woche nach dem normalen Unterricht statt.","ok": false}]},{"text": "… weil wir dabei Kinder aus anderen Klassen kennenlernen.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil die AGs jede Woche am Nachmittag stattfinden.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:handys","schwach": "Wir sollten Handys während der Gruppenarbeit weglegen. Das finde ich einfach passend. Ziel: in der Gruppe aufmerksam zusammenarbeiten.","optionen": [{"text": "… weil keine Nachricht mitten im Gespräch unsere Aufmerksamkeit ablenkt.","ok": true,"info": "Dieser Grund erklärt das Ziel: in der Gruppe aufmerksam zusammenarbeiten.","warum": [{"text": "Ohne Nachrichten werden wir im Gespräch seltener abgelenkt.","ok": true},{"text": "In der Tasche können die Geräte nicht vom Gruppentisch fallen.","ok": false},{"text": "Während der Gruppenarbeit liegen die Handys in unseren Taschen.","ok": false}]},{"text": "… weil wir die Geräte dann nicht aus Versehen fallen lassen.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil Handys während der Gruppenarbeit in den Taschen liegen.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:haustiere","schwach": "Wir sollten vor dem Tierkauf einen Pflegeplan machen. Das finde ich einfach passend. Ziel: die tägliche Versorgung des Tieres sichern.","optionen": [{"text": "… weil wir vorher klären, wer jeden Tag welche Aufgabe übernimmt.","ok": true,"info": "Dieser Grund erklärt das Ziel: die tägliche Versorgung des Tieres sichern.","warum": [{"text": "Der Plan klärt für jeden Tag die Zuständigkeit bei der Pflege.","ok": true},{"text": "Beim Planen können wir uns einen Namen für das Tier überlegen.","ok": false},{"text": "In einem Pflegeplan stehen mehrere Aufgaben und Kindernamen.","ok": false}]},{"text": "… weil wir dabei überlegen, welchen Namen das Tier bekommt.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil ein Pflegeplan mehrere Aufgaben und Namen enthalten kann.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:freizeit","schwach": "Wir sollten einen Nachmittag ohne feste Termine lassen. Das finde ich einfach passend. Ziel: Zeit für eigene Ideen finden.","optionen": [{"text": "… weil wir selbst entscheiden können, was wir beginnen möchten.","ok": true,"info": "Dieser Grund erklärt das Ziel: Zeit für eigene Ideen finden.","warum": [{"text": "In freier Zeit können wir selbst ein eigenes Vorhaben beginnen.","ok": true},{"text": "Für einen freien Nachmittag brauchen wir keine Kurstasche.","ok": false},{"text": "Ein freier Nachmittag hat keinen festen Platz im Kursplan.","ok": false}]},{"text": "… weil wir dann keine Sporttasche für einen Kurs packen müssen.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil ein freier Nachmittag nicht in unserem Kursplan steht.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:fahrrad","schwach": "Wir sollten Fahrräder vor dem Ausflug gemeinsam prüfen. Das finde ich einfach passend. Ziel: mit sicheren Fahrrädern losfahren.","optionen": [{"text": "… weil wir defekte Bremsen noch vor der Abfahrt entdecken.","ok": true,"info": "Dieser Grund erklärt das Ziel: mit sicheren Fahrrädern losfahren.","warum": [{"text": "Beim Test fallen kaputte Bremsen schon vor der Abfahrt auf.","ok": true},{"text": "Beim Treffen können wir die Fahrräder der anderen ansehen.","ok": false},{"text": "Vor dem Ausflug stehen viele Fahrräder auf unserem Schulhof.","ok": false}]},{"text": "… weil wir dabei die verschiedenen Fahrräder der Klasse ansehen.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil vor dem Ausflug viele Fahrräder auf dem Schulhof stehen.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:schulweg","schwach": "Wir sollten für den Schulweg sichere Querungen auswählen. Das finde ich einfach passend. Ziel: gefahrlos über viel befahrene Straßen kommen.","optionen": [{"text": "… weil wir an übersichtlichen Stellen den Verkehr besser sehen.","ok": true,"info": "Dieser Grund erklärt das Ziel: gefahrlos über viel befahrene Straßen kommen.","warum": [{"text": "An freien Querungen können wir den Verkehr besser sehen.","ok": true},{"text": "Auf dem gewählten Schulweg treffen wir andere Kinder häufiger.","ok": false},{"text": "Auf unserem Schulweg müssen wir mehrere Straßen überqueren.","ok": false}]},{"text": "… weil wir auf diesem Weg andere Kinder öfter treffen.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil auf unserem Schulweg mehrere Straßen überquert werden.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:umwelt","schwach": "Wir sollten in leeren Klassenräumen das Licht ausschalten. Das finde ich einfach passend. Ziel: unnötigen Stromverbrauch vermeiden.","optionen": [{"text": "… weil leere Räume keine Beleuchtung zum Arbeiten brauchen.","ok": true,"info": "Dieser Grund erklärt das Ziel: unnötigen Stromverbrauch vermeiden.","warum": [{"text": "Ohne Menschen im Raum ist keine Beleuchtung zum Arbeiten nötig.","ok": true},{"text": "Das Ausschalten erinnert uns an das Ende der Arbeitsphase.","ok": false},{"text": "An der Decke unserer Klassenräume hängen mehrere Lampen.","ok": false}]},{"text": "… weil wir dadurch an das Ende der Pause erinnert werden.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil in unseren Klassenräumen mehrere Lampen an der Decke hängen.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:muell","schwach": "Wir sollten Papier getrennt von Essensresten sammeln. Das finde ich einfach passend. Ziel: sauberes Papier wiederverwerten lassen.","optionen": [{"text": "… weil Essensreste das gesammelte Papier nicht verschmutzen.","ok": true,"info": "Dieser Grund erklärt das Ziel: sauberes Papier wiederverwerten lassen.","warum": [{"text": "Ohne Essensreste wird das gesammelte Papier nicht schmutzig.","ok": true},{"text": "Beim Trennen lernen wir unsere verschiedenen Abfalleimer kennen.","ok": false},{"text": "Papier und Essensreste gehören in unterschiedliche Abfalleimer.","ok": false}]},{"text": "… weil wir dadurch unsere verschiedenen Abfalleimer kennenlernen.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil Papier und Essensreste in verschiedene Eimer gehören.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:ausflug","schwach": "Wir sollten Ausflugsziele mit dem Bus erreichen können. Das finde ich einfach passend. Ziel: allen Kindern die Teilnahme ermöglichen.","optionen": [{"text": "… weil niemand für die Anfahrt ein eigenes Auto braucht.","ok": true,"info": "Dieser Grund erklärt das Ziel: allen Kindern die Teilnahme ermöglichen.","warum": [{"text": "Im Bus kann man auch ohne eigenes Auto zum Ziel mitkommen.","ok": true},{"text": "Bei der Busfahrt können wir die Landschaft unterwegs ansehen.","ok": false},{"text": "Der Bus fährt an einer Haltestelle vor unserer Schule ab.","ok": false}]},{"text": "… weil wir während der Fahrt die Landschaft anschauen können.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil der Bus an einer Haltestelle vor unserer Schule abfährt.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:klassenfest","schwach": "Wir sollten für das Klassenfest verschiedene Aufgaben anbieten. Das finde ich einfach passend. Ziel: jedem Kind eine passende Beteiligung ermöglichen.","optionen": [{"text": "… weil auch Kinder ohne Bühnenmut einen Beitrag leisten können.","ok": true,"info": "Dieser Grund erklärt das Ziel: jedem Kind eine passende Beteiligung ermöglichen.","warum": [{"text": "Auch ohne Bühnenmut können Kinder einen Beitrag leisten.","ok": true},{"text": "Bei verschiedenen Aufgaben sammeln wir mehr Ideen für das Fest.","ok": false},{"text": "Beim Klassenfest müssen mehrere Aufgaben gleichzeitig erledigt werden.","ok": false}]},{"text": "… weil wir dadurch mehr verschiedene Dinge für das Fest sammeln.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil beim Klassenfest mehrere Aufgaben nebeneinander anfallen.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:gruppenarbeit","schwach": "Wir sollten in Gruppen klare Aufgaben absprechen. Das finde ich einfach passend. Ziel: doppelte Arbeit und vergessene Teile vermeiden.","optionen": [{"text": "… weil jeder weiß, welchen Teil der Aufgabe er übernimmt.","ok": true,"info": "Dieser Grund erklärt das Ziel: doppelte Arbeit und vergessene Teile vermeiden.","warum": [{"text": "Durch Absprachen kennt jeder seinen eigenen Teil der Aufgabe.","ok": true},{"text": "Bei der Absprache können wir mit neuen Partnern sprechen.","ok": false},{"text": "In einer Arbeitsgruppe sitzen mehrere Kinder an einem Tisch.","ok": false}]},{"text": "… weil wir dadurch öfter mit neuen Partnern sprechen können.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil in unserer Gruppe mehrere Kinder an einem Tisch sitzen.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:bibliothek","schwach": "Wir sollten Bücher in der Klassenbibliothek beschriften. Das finde ich einfach passend. Ziel: passende Bücher schneller finden.","optionen": [{"text": "… weil wir am Schild sofort das Thema eines Regals erkennen.","ok": true,"info": "Dieser Grund erklärt das Ziel: passende Bücher schneller finden.","warum": [{"text": "Die Schilder zeigen sofort, welches Thema ein Regal enthält.","ok": true},{"text": "Mit selbst gemalten Schildern können wir Bilder im Raum zeigen.","ok": false},{"text": "Die Bücher unserer Klassenbibliothek stehen in mehreren Regalen.","ok": false}]},{"text": "… weil wir unsere selbst gemalten Schilder im Raum zeigen können.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil Bücher in unserer Klassenbibliothek in Regalen stehen.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:schulessen","schwach": "Wir sollten beim Schulessen kleine erste Portionen wählen. Das finde ich einfach passend. Ziel: weniger gutes Essen wegwerfen.","optionen": [{"text": "… weil wir erst nachnehmen, wenn wir noch Hunger haben.","ok": true,"info": "Dieser Grund erklärt das Ziel: weniger gutes Essen wegwerfen.","warum": [{"text": "Beim Nachnehmen passt die Essensmenge besser zum Hunger.","ok": true},{"text": "Mit kleinen Portionen können wir verschiedene Teller erproben.","ok": false},{"text": "An der Ausgabe stehen für die Kinder mehrere Stapel Teller bereit.","ok": false}]},{"text": "… weil wir dadurch verschiedene Tellergrößen ausprobieren können.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil beim Mittagessen Teller an der Ausgabe bereitstehen.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:trinken","schwach": "Wir sollten Wasserflaschen im Klassenraum auffüllen können. Das finde ich einfach passend. Ziel: beim Lernen genug Wasser trinken.","optionen": [{"text": "… weil leere Flaschen auch während des Schultags wieder gefüllt werden.","ok": true,"info": "Dieser Grund erklärt das Ziel: beim Lernen genug Wasser trinken.","warum": [{"text": "An der Füllstelle werden leere Flaschen wieder gefüllt.","ok": true},{"text": "Mit eigenen Flaschen müssen wir keine fremden Becher benutzen.","ok": false},{"text": "Unsere Trinkflaschen haben verschiedene Größen und Farben.","ok": false}]},{"text": "… weil wir unsere Flaschen nicht mit anderen verwechseln müssen.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil unsere Trinkflaschen verschiedene Farben und Größen haben.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:lesezeit","schwach": "Wir sollten eine kurze stille Lesezeit einführen. Das finde ich einfach passend. Ziel: ohne Unterbrechung in Geschichten eintauchen.","optionen": [{"text": "… weil alle gleichzeitig lesen und niemand dazwischen spricht.","ok": true,"info": "Dieser Grund erklärt das Ziel: ohne Unterbrechung in Geschichten eintauchen.","warum": [{"text": "Wenn alle still lesen, spricht niemand in die Geschichte hinein.","ok": true},{"text": "In der Lesezeit können wir unsere Lieblingsbücher zeigen.","ok": false},{"text": "In der Lesezeit liegen viele Bücher auf den Tischen im Raum.","ok": false}]},{"text": "… weil wir dabei unsere mitgebrachten Lieblingsbücher zeigen können.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil in der Lesezeit Bücher auf unseren Tischen liegen.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:partnerwahl","schwach": "Wir sollten bei kurzen Partneraufgaben gelegentlich auslosen. Das finde ich einfach passend. Ziel: mit verschiedenen Kindern zusammenarbeiten lernen.","optionen": [{"text": "… weil wir auch mit Kindern außerhalb des Freundeskreises üben.","ok": true,"info": "Dieser Grund erklärt das Ziel: mit verschiedenen Kindern zusammenarbeiten lernen.","warum": [{"text": "Durch Lose üben wir auch mit Kindern außerhalb unserer Freunde.","ok": true},{"text": "Beim Losen können wir unsere eigenen Namenskärtchen nutzen.","ok": false},{"text": "Bei einer Partneraufgabe arbeiten jeweils zwei Kinder zusammen.","ok": false}]},{"text": "… weil wir durch das Losen unsere Namenskärtchen nutzen können.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil bei Partneraufgaben jeweils zwei Kinder zusammenarbeiten.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:ordnung","schwach": "Wir sollten gemeinsam benutztes Material fest einsortieren. Das finde ich einfach passend. Ziel: benötigte Sachen ohne langes Suchen finden.","optionen": [{"text": "… weil jeder den gleichen Platz für Schere und Kleber kennt.","ok": true,"info": "Dieser Grund erklärt das Ziel: benötigte Sachen ohne langes Suchen finden.","warum": [{"text": "Ein fester Platz zeigt allen, wo Schere und Kleber liegen.","ok": true},{"text": "Beim Einsortieren können wir unsere Materialkisten bemalen.","ok": false},{"text": "Scheren und Kleber gehören gemeinsam zu unserem Bastelmaterial.","ok": false}]},{"text": "… weil wir dabei unsere Materialkisten neu bemalen können.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil Scheren und Kleber zusammen zu unserem Bastelmaterial gehören.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:spielregeln","schwach": "Wir sollten Spielregeln vor dem Turnier gemeinsam klären. Das finde ich einfach passend. Ziel: Streit über unklare Entscheidungen vermeiden.","optionen": [{"text": "… weil wir schon vor dem Spiel wissen, welche Regeln gelten.","ok": true,"info": "Dieser Grund erklärt das Ziel: Streit über unklare Entscheidungen vermeiden.","warum": [{"text": "Nach dem Klären wissen beide Teams, welche Regeln gelten.","ok": true},{"text": "Vor dem Turnier erfahren wir die Namen der Mannschaften.","ok": false},{"text": "Bei einem Turnier spielen mehrere Mannschaften gegeneinander.","ok": false}]},{"text": "… weil wir dabei die Namen der anderen Mannschaften erfahren.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil zu einem Turnier mehrere Spiele zwischen Teams gehören.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:radstaender","schwach": "Wir sollten Fahrräder an festen Plätzen abstellen. Das finde ich einfach passend. Ziel: den Eingang zur Schule frei halten.","optionen": [{"text": "… weil kein Rad mitten im Weg vor der Eingangstür steht.","ok": true,"info": "Dieser Grund erklärt das Ziel: den Eingang zur Schule frei halten.","warum": [{"text": "Mit festen Plätzen steht kein Rad vor unserer Eingangstür.","ok": true},{"text": "Bei festen Plätzen finden wir die Räder unserer Freunde leichter.","ok": false},{"text": "Die Fahrradständer unserer Schule stehen neben dem Eingang.","ok": false}]},{"text": "… weil wir dort die Fahrräder unserer Freunde wiederfinden können.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil unsere Schule mehrere Fahrradständer neben dem Eingang hat.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:tauschregal","schwach": "Wir sollten ein Tauschregal für brauchbare Schulsachen aufstellen. Das finde ich einfach passend. Ziel: gut erhaltene Dinge länger nutzen.","optionen": [{"text": "… weil andere Kinder noch verwendbare Sachen weiterbenutzen können.","ok": true,"info": "Dieser Grund erklärt das Ziel: gut erhaltene Dinge länger nutzen.","warum": [{"text": "Im Regal können andere die noch guten Sachen weiterbenutzen.","ok": true},{"text": "Beim Tauschen entdecken wir verschiedene Farben und Muster.","ok": false},{"text": "In einem Tauschregal liegen verschiedene Sachen zum Mitnehmen.","ok": false}]},{"text": "… weil wir dabei verschiedene Farben und Muster entdecken.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil in einem Tauschregal Sachen zum Mitnehmen bereitliegen.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]},
    {"id": "VERBESSERN:lernpause","schwach": "Wir sollten bei langen Arbeitsphasen kurze Bewegungspausen machen. Das finde ich einfach passend. Ziel: nach langem Sitzen wieder aufmerksam arbeiten.","optionen": [{"text": "… weil wir die sitzende Haltung kurz unterbrechen können.","ok": true,"info": "Dieser Grund erklärt das Ziel: nach langem Sitzen wieder aufmerksam arbeiten.","warum": [{"text": "In Bewegungspausen unterbrechen wir das lange Sitzen.","ok": true},{"text": "In der Pause können wir unsere gewählten Bewegungen zeigen.","ok": false},{"text": "Eine Bewegungspause unterbricht unsere lange Arbeitsphase.","ok": false}]},{"text": "… weil wir dabei unsere selbst gewählten Bewegungen zeigen können.","ok": false,"info": "Das ist ein anderer Vorteil. Er erklärt das genannte Ziel nicht."},{"text": "… weil eine Bewegungspause unsere lange Arbeitsphase unterbricht.","ok": false,"info": "Das beschreibt die Handlung, erklärt aber ihren Nutzen nicht."}]}
  ];
  /* Tiefe 4 (Kapitel 2): Spricht der Satz dafür oder dagegen? */
  ZI.DAFUER_DAGEGEN = [
    {"id": "DAFUER_DAGEGEN:pausenecke","kopf": "Wir sollten eine ruhige Pausenecke einrichten.","karten": [{"text": "Eine ruhige Ecke lässt uns abschalten und neue Kraft sammeln.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Wer sich ausruht, muss nicht die ganze Pause auf Lärm achten.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Für Ballspiele bleibt dann weniger Platz auf dem Hof.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Manche Kinder könnten den ruhigen Platz allein für sich beanspruchen.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:hausaufgaben","kopf": "Wir sollten Hausaufgaben am Ende gemeinsam notieren.","karten": [{"text": "Beim Vergleich mit der Tafel entdecken wir fehlende Aufgaben.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Ein gemeinsamer Blick zeigt, ob eine Aufgabe im Eintrag fehlt.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Das gemeinsame Notieren kostet Zeit am Stundenende.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Wer die Tafel schlecht sieht, kann seinen Eintrag nicht vergleichen.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:schulbeginn","kopf": "Wir sollten eine Woche lang später mit der Schule beginnen.","karten": [{"text": "Ein Vergleich beider Wochen zeigt, wie müde wir jeweils sind.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Ein Vergleich beider Wochen zeigt Unterschiede in der Müdigkeit.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Unser Schulbus fährt nur zu den bisherigen Zeiten.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Durch den späteren Beginn enden die Nachmittagskurse ebenfalls später.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:sitzordnung","kopf": "Wir sollten einen freien Blick auf die Tafel ermöglichen.","karten": [{"text": "Mit freier Sicht müssen wir nicht um andere herumsehen.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Ein freies Sichtfeld hilft auch den Kindern in der letzten Reihe.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Beim Umstellen könnten die Laufwege zu schmal werden.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Manche Kinder wollen weiter neben ihren bisherigen Freunden sitzen.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:klassenregel","kopf": "Wir sollten eine feste Reihenfolge beim Sprechen nutzen.","karten": [{"text": "In der Reihenfolge übertönen andere keine leisen Stimmen.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Wer auf seinen Einsatz wartet, überdeckt die leise Stimme nicht.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Manchmal will jemand sofort eine wichtige Frage stellen.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Einige Kinder trauen sich auch in der Reihenfolge nicht zu sprechen.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:dienste","kopf": "Wir sollten die Klassendienste jede Woche wechseln.","karten": [{"text": "Beim Wechsel erledigen nicht immer dieselben Kinder die Arbeit.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Auch unbeliebte Dienste werden beim Wechsel von allen übernommen.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Neue Kinder wissen oft noch nicht, wie ein Dienst geht.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Manche Dienste brauchen viel länger als andere im Klassenraum.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:klassenfahrt","kopf": "Wir sollten bei der Klassenfahrt gemeinsame Aufgaben planen.","karten": [{"text": "Bei gemeinsamen Aufgaben sind wir aufeinander angewiesen.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Bei gemeinsamen Aufgaben hört man auch die Ideen neuer Partner.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Bei einem Wettbewerb können schwächere Kinder ausgeschlossen werden.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Bei einer Wegsuche könnten Gruppen den vereinbarten Bereich verlassen.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:schulhof","kopf": "Wir sollten Spielgeräte in der Pause ausleihen können.","karten": [{"text": "Die Ausleihe ermöglicht Spiele auch ohne eigene Geräte.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Fehlende eigene Spielsachen schließen dann niemanden vom Spiel aus.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Manche Geräte werden vielleicht nicht wieder zurückgebracht.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Bei der Ausgabe könnten lange Schlangen die ganze Pause verbrauchen.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:sport","kopf": "Wir sollten im Sport verschiedene Spielarten ausprobieren.","karten": [{"text": "Bei verschiedenen Spielen zählen unterschiedliche Fähigkeiten.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Wer langsam läuft, kann bei einer anderen Aufgabe trotzdem helfen.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Bei ständig neuen Spielen geht viel Zeit fürs Erklären verloren.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Einige neue Spiele könnten für Kinder mit Verletzungen ungeeignet sein.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:ags","kopf": "Wir sollten vor der AG-Wahl Schnupperstunden anbieten.","karten": [{"text": "Beim Schnuppern können wir die Tätigkeit vor der Wahl testen.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Ein eigener Versuch zeigt besser als ein Name, was man gern macht.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Für mehrere Schnupperstunden fehlt uns die freie Zeit.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Beliebte Schnupper-AGs könnten viel zu große Gruppen bekommen.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:handys","kopf": "Wir sollten Handys während der Gruppenarbeit weglegen.","karten": [{"text": "Ohne Nachrichten werden wir im Gespräch seltener abgelenkt.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Ohne Blick aufs Display bemerkt man Fragen der anderen schneller.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Für manche Aufgaben brauchen wir das Handy zum Nachschlagen.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Eine Familie muss ein Kind in einem dringenden Fall erreichen können.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:haustiere","kopf": "Wir sollten vor dem Tierkauf einen Pflegeplan machen.","karten": [{"text": "Der Plan klärt für jeden Tag die Zuständigkeit bei der Pflege.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Feste Zuständigkeiten helfen auch am Wochenende gegen vergessene Pflege.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "In den Ferien ist vielleicht die ganze Familie unterwegs.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Vielleicht vergisst jemand trotz Pflegeplan seinen Dienst am Nachmittag.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:freizeit","kopf": "Wir sollten einen Nachmittag ohne feste Termine lassen.","karten": [{"text": "In freier Zeit können wir selbst ein eigenes Vorhaben beginnen.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Ohne fertigen Kursplan entsteht Raum für selbst gewählte Vorhaben.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Ein fester freier Nachmittag könnte mit einem beliebten Kurs zusammenfallen.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Ein freier Nachmittag hilft wenig, wenn kein Spielmaterial vorhanden ist.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:fahrrad","kopf": "Wir sollten Fahrräder vor dem Ausflug gemeinsam prüfen.","karten": [{"text": "Beim Test fallen kaputte Bremsen schon vor der Abfahrt auf.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Ein vorher entdeckter Fehler kann noch vor der Fahrt behoben werden.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Nicht alle Kinder können eine kaputte Bremse reparieren.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Der gemeinsame Check könnte bei vielen Rädern zu lange dauern.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:schulweg","kopf": "Wir sollten für den Schulweg sichere Querungen auswählen.","karten": [{"text": "An freien Querungen können wir den Verkehr besser sehen.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Gute Sicht lässt mehr Zeit, ein herannahendes Auto zu bemerken.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Der Weg zur übersichtlichen Querung ist etwas länger.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "An einer sicheren Querung könnte während des Schulwegs gebaut werden.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:umwelt","kopf": "Wir sollten in leeren Klassenräumen das Licht ausschalten.","karten": [{"text": "Ohne Menschen im Raum ist keine Beleuchtung zum Arbeiten nötig.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Eine ausgeschaltete Lampe verbraucht in dieser Zeit keinen Strom.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Das letzte Kind vergisst das Ausschalten vielleicht im Alltag.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Wer im Raum bleibt, braucht vielleicht weiter Licht zum Lesen.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:muell","kopf": "Wir sollten Papier getrennt von Essensresten sammeln.","karten": [{"text": "Ohne Essensreste wird das gesammelte Papier nicht schmutzig.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Sauberes Altpapier lässt sich besser für neue Papierwaren nutzen.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Manche Kinder wissen nicht, welcher Abfall wohin gehört.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Ein übervoller Papiereimer könnte Papier auf dem Boden verteilen.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:ausflug","kopf": "Wir sollten Ausflugsziele mit dem Bus erreichen können.","karten": [{"text": "Im Bus kann man auch ohne eigenes Auto zum Ziel mitkommen.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Eine gemeinsame Anfahrt hängt nicht vom Auto der Eltern ab.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Die Busfahrt macht den Ausflug für Familien teurer.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Auf der langen Busfahrt könnte manchen Kindern schlecht werden.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:klassenfest","kopf": "Wir sollten für das Klassenfest verschiedene Aufgaben anbieten.","karten": [{"text": "Auch ohne Bühnenmut können Kinder einen Beitrag leisten.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Wer nicht vor allen sprechen will, hilft trotzdem bei der Vorbereitung.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Beliebte Aufgaben werden vielleicht von zu vielen Kindern gewählt.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Manche Aufgaben beim Klassenfest sind viel aufwendiger als andere.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:gruppenarbeit","kopf": "Wir sollten in Gruppen klare Aufgaben absprechen.","karten": [{"text": "Durch Absprachen kennt jeder seinen eigenen Teil der Aufgabe.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Klare Zuständigkeiten zeigen, welcher Teil noch nicht bearbeitet ist.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Eine Aufgabe kann für ein Kind zu schwer sein.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Feste Aufgaben könnten verhindern, dass Kinder neue Dinge lernen.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:bibliothek","kopf": "Wir sollten Bücher in der Klassenbibliothek beschriften.","karten": [{"text": "Die Schilder zeigen sofort, welches Thema ein Regal enthält.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Wer ein Thema sucht, muss dann nicht jedes Buch einzeln herausziehen.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Zu viele kleine Gruppen können die Suche unübersichtlich machen.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Einige Kinder können die Wörter auf den Regalschildern noch nicht lesen.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:schulessen","kopf": "Wir sollten beim Schulessen kleine erste Portionen wählen.","karten": [{"text": "Beim Nachnehmen passt die Essensmenge besser zum Hunger.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Auf dem Teller bleibt weniger zurück, wenn die Menge zum Hunger passt.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Langes Anstehen zum Nachholen könnte die Essenszeit verkürzen.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Bei warmen Gerichten könnte bis zum Nachnehmen das Essen kalt werden.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:trinken","kopf": "Wir sollten Wasserflaschen im Klassenraum auffüllen können.","karten": [{"text": "An der Füllstelle werden leere Flaschen wieder gefüllt.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Eine erreichbare Füllstelle hilft auch nach einer vergessenen Füllung.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Am Wasserhahn könnte mitten im Unterricht eine Schlange entstehen.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Beim Füllen könnte verschüttetes Wasser den Boden rutschig machen.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:lesezeit","kopf": "Wir sollten eine kurze stille Lesezeit einführen.","karten": [{"text": "Wenn alle still lesen, spricht niemand in die Geschichte hinein.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Stille hilft, den Zusammenhang zwischen mehreren Seiten zu behalten.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Einige Kinder brauchen beim Lesen einzelner Wörter Unterstützung.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Ausgeliehene Bücher könnten nach der Lesezeit nicht wieder zurückkommen.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:partnerwahl","kopf": "Wir sollten bei kurzen Partneraufgaben gelegentlich auslosen.","karten": [{"text": "Durch Lose üben wir auch mit Kindern außerhalb unserer Freunde.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Neue Partner zeigen, wie andere Kinder an dieselbe Aufgabe herangehen.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Ein zugelostes Paar könnte bei einer Aufgabe gar nicht weiterkommen.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Schnelle Kinder könnten sofort antworten, bevor ihr Partner nachgedacht hat.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:ordnung","kopf": "Wir sollten gemeinsam benutztes Material fest einsortieren.","karten": [{"text": "Ein fester Platz zeigt allen, wo Schere und Kleber liegen.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Ein fester Platz hilft auch Kindern, die das Material nicht weggeräumt haben.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Beim schnellen Aufräumen könnte Material im falschen Fach landen.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Die beschrifteten Materialfächer könnten für kleine Kinder zu hoch sein.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:spielregeln","kopf": "Wir sollten Spielregeln vor dem Turnier gemeinsam klären.","karten": [{"text": "Nach dem Klären wissen beide Teams, welche Regeln gelten.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Eine bekannte Regel bietet beiden Seiten dieselbe Grundlage bei Streit.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Bis wir uns geeinigt haben, bleibt weniger Zeit zum Spielen.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Beim Turnier könnten sich beide Mannschaften an verschiedene Absprachen erinnern.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:radstaender","kopf": "Wir sollten Fahrräder an festen Plätzen abstellen.","karten": [{"text": "Mit festen Plätzen steht kein Rad vor unserer Eingangstür.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Ein freier Eingang lässt auch mit einer großen Tasche genug Durchgang.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Die vorhandenen Ständer reichen nicht für alle Fahrräder aus.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Ein Fahrrad könnte auch im Ständer einen schmalen Durchgang versperren.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:tauschregal","kopf": "Wir sollten ein Tauschregal für brauchbare Schulsachen aufstellen.","karten": [{"text": "Im Regal können andere die noch guten Sachen weiterbenutzen.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Was weiterverwendet wird, muss nicht gleich neu gekauft werden.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Im Regal könnten kaputte oder unbrauchbare Sachen landen.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Einige Kinder könnten gleich alle brauchbaren Sachen aus dem Regal nehmen.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]},
    {"id": "DAFUER_DAGEGEN:lernpause","kopf": "Wir sollten bei langen Arbeitsphasen kurze Bewegungspausen machen.","karten": [{"text": "In Bewegungspausen unterbrechen wir das lange Sitzen.","ja": true,"info": "Dieser Nutzen spricht für den Vorschlag."},{"text": "Ein kurzer Wechsel der Haltung erleichtert einen neuen Arbeitsbeginn.","ja": true,"info": "Diese Folge stützt den Vorschlag."},{"text": "Nach einer Pause finden manche Kinder schwer zurück zur Aufgabe.","ja": false,"info": "Diese Schwierigkeit spricht gegen den Vorschlag."},{"text": "Bei Bewegung im Raum könnten Kinder an Tischkanten stoßen.","ja": false,"info": "Das ist ein weiterer Nachteil des Vorschlags."}]}
  ];

