    {"id": "STAERKER_BELEGT:pausenecke","meinung": "Wir sollten eine ruhige Pausenecke einrichten. Ziel: nach der Pause konzentriert lernen.","optionen": [{"text": "Wir sollten eine ruhige Pausenecke einrichten, weil wir dort abschalten und neue Kraft sammeln. Nach zehn ruhigen Minuten konnte Mila wieder ihrer Aufgabe folgen.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: Eine ruhige Ecke lässt uns abschalten und neue Kraft sammeln.","ok": true},{"text": "Im Beispiel wird sichtbar: In der Ecke können wir Karten mit unseren Freunden tauschen.","ok": false},{"text": "Im Beispiel wird sichtbar: Die Pausenecke befindet sich auf einem Teil unseres Schulhofs.","ok": false}]},{"text": "Wir sollten eine ruhige Pausenecke einrichten, weil wir dort abschalten und neue Kraft sammeln. Mila traf in der neuen Ecke ihre Freundin aus der Nachbarklasse.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten eine ruhige Pausenecke einrichten, weil wir dort Karten mit Freunden tauschen können. Die neue Sitzbank steht neben der Mauer und hat drei breite Holzbretter.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:hausaufgaben","meinung": "Wir sollten Hausaufgaben am Ende gemeinsam notieren. Ziel: keine Aufgabe beim Aufschreiben übersehen.","optionen": [{"text": "Wir sollten Hausaufgaben am Ende gemeinsam notieren, weil wir die Einträge noch mit der Tafel vergleichen. Omar bemerkte beim Vergleich die fehlende zweite Matheaufgabe.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: Beim Vergleich mit der Tafel entdecken wir fehlende Aufgaben.","ok": true},{"text": "Im Beispiel wird sichtbar: Beim Notieren können wir unsere Hefte ordentlich gestalten.","ok": false},{"text": "Im Beispiel wird sichtbar: Nach dem Aufschreiben stehen die Aufgaben in unseren Heften.","ok": false}]},{"text": "Wir sollten Hausaufgaben am Ende gemeinsam notieren, weil wir die Einträge noch mit der Tafel vergleichen. Omar schrieb das Datum mit einem neuen blauen Stift ins Heft.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten Hausaufgaben am Ende gemeinsam notieren, weil wir dabei unsere Hefte ordentlich gestalten. Auf der Tafel standen die Hausaufgaben heute unter dem Datum der Stunde.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:schulbeginn","meinung": "Wir sollten eine Woche lang später mit der Schule beginnen. Ziel: prüfen, ob wir morgens wacher lernen.","optionen": [{"text": "Wir sollten eine Woche lang später mit der Schule beginnen, weil wir unsere Müdigkeit vor und nach dem Versuch vergleichen. Nora notierte jeden Morgen, wie wach sie in der ersten Stunde war.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: Ein Vergleich beider Wochen zeigt, wie müde wir jeweils sind.","ok": true},{"text": "Im Beispiel wird sichtbar: Vor dem späteren Beginn können wir gemeinsam frühstücken.","ok": false},{"text": "Im Beispiel wird sichtbar: Beim späteren Beginn startet der Unterricht zu einer neuen Uhrzeit.","ok": false}]},{"text": "Wir sollten eine Woche lang später mit der Schule beginnen, weil wir unsere Müdigkeit vor und nach dem Versuch vergleichen. Nora nahm in der Versuchswoche jeden Morgen ein belegtes Brot mit.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten eine Woche lang später mit der Schule beginnen, weil wir morgens gemeinsam in Ruhe frühstücken können. In der ersten Stunde nach dem neuen Beginn saß Nora wieder am Fenster.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:sitzordnung","meinung": "Wir sollten einen freien Blick auf die Tafel ermöglichen. Ziel: die Tafel von jedem Platz gut erkennen.","optionen": [{"text": "Wir sollten einen freien Blick auf die Tafel ermöglichen, weil keiner beim Lesen um andere herumsehen muss. Lina konnte die Rechnung nach dem Umstellen ohne Aufstehen lesen.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: Mit freier Sicht müssen wir nicht um andere herumsehen.","ok": true},{"text": "Im Beispiel wird sichtbar: Nach dem Umstellen können wir unsere Freunde leichter sehen.","ok": false},{"text": "Im Beispiel wird sichtbar: Die Tafel hängt an der vorderen Wand unseres Klassenraums.","ok": false}]},{"text": "Wir sollten einen freien Blick auf die Tafel ermöglichen, weil keiner beim Lesen um andere herumsehen muss. Lina saß nach dem Umstellen neben ihrem besten Freund Noah.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten einen freien Blick auf die Tafel ermöglichen, weil wir unsere Freunde im Raum leichter sehen können. Nach dem Umstellen stand ein Tisch näher am Schrank als vorher am Fenster.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:klassenregel","meinung": "Wir sollten eine feste Reihenfolge beim Sprechen nutzen. Ziel: leise Stimmen im Klassenrat besser hören.","optionen": [{"text": "Wir sollten eine feste Reihenfolge beim Sprechen nutzen, weil jeder reden kann, ohne von anderen übertönt zu werden. Als Amira an der Reihe war, hörten alle ihren Vorschlag bis zum Ende.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: In der Reihenfolge übertönen andere keine leisen Stimmen.","ok": true},{"text": "Im Beispiel wird sichtbar: Vor dem Sprechen können wir unsere Beiträge aufschreiben.","ok": false},{"text": "Im Beispiel wird sichtbar: Im Klassenrat sprechen mehrere Kinder nacheinander über ein Thema.","ok": false}]},{"text": "Wir sollten eine feste Reihenfolge beim Sprechen nutzen, weil jeder reden kann, ohne von anderen übertönt zu werden. Amira schrieb vor dem Klassenrat zwei Ideen auf eine Karte.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten eine feste Reihenfolge beim Sprechen nutzen, weil wir unsere Beiträge dabei vorher aufschreiben können. Amiras Redekarte war auf beiden Seiten mit einem kleinen Stern bemalt.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:dienste","meinung": "Wir sollten die Klassendienste jede Woche wechseln. Ziel: die Arbeit in der Klasse fair verteilen.","optionen": [{"text": "Wir sollten die Klassendienste jede Woche wechseln, weil nicht jede Woche dieselben Kinder alles erledigen. Diese Woche fegt Ben, nächste Woche übernimmt Elif seinen Dienst.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: Beim Wechsel erledigen nicht immer dieselben Kinder die Arbeit.","ok": true},{"text": "Im Beispiel wird sichtbar: Durch den Wechsel lernen wir unterschiedliche Dienste kennen.","ok": false},{"text": "Im Beispiel wird sichtbar: Auf dem Dienstplan stehen in jeder Woche andere Kindernamen.","ok": false}]},{"text": "Wir sollten die Klassendienste jede Woche wechseln, weil nicht jede Woche dieselben Kinder alles erledigen. Ben lernte beim Blumendienst den Namen unserer Zimmerpflanze.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten die Klassendienste jede Woche wechseln, weil wir verschiedene Aufgaben im Klassenraum kennenlernen. Am Dienstplan hängt neben Bens Namen ein selbst gezeichnetes Besensymbol.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:klassenfahrt","meinung": "Wir sollten bei der Klassenfahrt gemeinsame Aufgaben planen. Ziel: uns als Klasse besser kennenlernen.","optionen": [{"text": "Wir sollten bei der Klassenfahrt gemeinsame Aufgaben planen, weil wir beim Lösen einer Aufgabe aufeinander angewiesen sind. Bei der Wegsuche erklärten sich zwei sonst fremde Kinder ihre Ideen.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: Bei gemeinsamen Aufgaben sind wir aufeinander angewiesen.","ok": true},{"text": "Im Beispiel wird sichtbar: Auf der Fahrt können wir die Wege um die Unterkunft erkunden.","ok": false},{"text": "Im Beispiel wird sichtbar: Eine Klassenfahrt dauert meist mehrere aufeinanderfolgende Tage.","ok": false}]},{"text": "Wir sollten bei der Klassenfahrt gemeinsame Aufgaben planen, weil wir beim Lösen einer Aufgabe aufeinander angewiesen sind. Bei der Wegsuche entdeckte die Gruppe einen großen alten Baum.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten bei der Klassenfahrt gemeinsame Aufgaben planen, weil wir dabei die Wege rund um die Unterkunft erkunden. Bei der gemeinsamen Wegsuche hatten alle Kinder die gleichen roten Mützen auf.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:schulhof","meinung": "Wir sollten Spielgeräte in der Pause ausleihen können. Ziel: mehr Kindern verschiedene Spiele ermöglichen.","optionen": [{"text": "Wir sollten Spielgeräte in der Pause ausleihen können, weil auch Kinder ohne eigenes Gerät etwas ausprobieren können. Ivo hatte kein Springseil dabei und konnte sich eines ausleihen.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: Die Ausleihe ermöglicht Spiele auch ohne eigene Geräte.","ok": true},{"text": "Im Beispiel wird sichtbar: Bei der Ausgabe lernen wir die Namen anderer Kinder kennen.","ok": false},{"text": "Im Beispiel wird sichtbar: Die ausgeliehenen Geräte werden am Ende der Pause zurückgegeben.","ok": false}]},{"text": "Wir sollten Spielgeräte in der Pause ausleihen können, weil auch Kinder ohne eigenes Gerät etwas ausprobieren können. Ivo gab sein ausgeliehenes Seil am Ende bei einem neuen Kind ab.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten Spielgeräte in der Pause ausleihen können, weil wir beim Ausleihen die Namen der anderen besser lernen. Das Springseil aus der Ausleihe hatte zwei grüne Griffe und ein langes Seil.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:sport","meinung": "Wir sollten im Sport verschiedene Spielarten ausprobieren. Ziel: unterschiedliche Stärken der Kinder entdecken.","optionen": [{"text": "Wir sollten im Sport verschiedene Spielarten ausprobieren, weil nicht in jedem Spiel dieselben Fähigkeiten zählen. Beim Zielwerfen war Sam stark, beim Laufspiel half Mara dem Team.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: Bei verschiedenen Spielen zählen unterschiedliche Fähigkeiten.","ok": true},{"text": "Im Beispiel wird sichtbar: Durch neue Spiele lernen wir verschiedene Spielnamen kennen.","ok": false},{"text": "Im Beispiel wird sichtbar: Zu verschiedenen Spielen gehören eigene Regeln und Materialien.","ok": false}]},{"text": "Wir sollten im Sport verschiedene Spielarten ausprobieren, weil nicht in jedem Spiel dieselben Fähigkeiten zählen. Beim Zielwerfen verwendete Sam einen weichen roten Schaumstoffball.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten im Sport verschiedene Spielarten ausprobieren, weil wir dabei die Namen vieler neuer Spiele kennenlernen. Zum Laufspiel stellte die Lehrerin sechs blaue Hütchen am Rand der Halle auf.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:ags","meinung": "Wir sollten vor der AG-Wahl Schnupperstunden anbieten. Ziel: eine passende AG auswählen.","optionen": [{"text": "Wir sollten vor der AG-Wahl Schnupperstunden anbieten, weil wir vor der Wahl die Tätigkeit selbst ausprobieren. Nach dem Bauen eines Modells wusste Deniz, dass die Werk-AG passt.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: Beim Schnuppern können wir die Tätigkeit vor der Wahl testen.","ok": true},{"text": "Im Beispiel wird sichtbar: Beim Schnuppern lernen wir Kinder aus anderen Klassen kennen.","ok": false},{"text": "Im Beispiel wird sichtbar: Die AGs finden jede Woche nach dem normalen Unterricht statt.","ok": false}]},{"text": "Wir sollten vor der AG-Wahl Schnupperstunden anbieten, weil wir vor der Wahl die Tätigkeit selbst ausprobieren. Beim Bauen des Modells lernte Deniz zwei Kinder aus Klasse sechs kennen.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten vor der AG-Wahl Schnupperstunden anbieten, weil wir dabei Kinder aus anderen Klassen kennenlernen. Das Modell aus der Werk-AG stand später auf dem Regal direkt neben der Tür.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:handys","meinung": "Wir sollten Handys während der Gruppenarbeit weglegen. Ziel: in der Gruppe aufmerksam zusammenarbeiten.","optionen": [{"text": "Wir sollten Handys während der Gruppenarbeit weglegen, weil keine Nachricht mitten im Gespräch unsere Aufmerksamkeit ablenkt. Ohne Nachrichtenton hörte Jona den Vorschlag seiner Partnerin zu Ende.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: Ohne Nachrichten werden wir im Gespräch seltener abgelenkt.","ok": true},{"text": "Im Beispiel wird sichtbar: In der Tasche können die Geräte nicht vom Gruppentisch fallen.","ok": false},{"text": "Im Beispiel wird sichtbar: Während der Gruppenarbeit liegen die Handys in unseren Taschen.","ok": false}]},{"text": "Wir sollten Handys während der Gruppenarbeit weglegen, weil keine Nachricht mitten im Gespräch unsere Aufmerksamkeit ablenkt. Jona legte sein Handy vor der Arbeit in eine gepolsterte Tasche.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten Handys während der Gruppenarbeit weglegen, weil wir die Geräte dann nicht aus Versehen fallen lassen. Vor der Gruppenarbeit zeigte Jona sein neues Hintergrundbild auf dem Handy.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:haustiere","meinung": "Wir sollten vor dem Tierkauf einen Pflegeplan machen. Ziel: die tägliche Versorgung des Tieres sichern.","optionen": [{"text": "Wir sollten vor dem Tierkauf einen Pflegeplan machen, weil wir vorher klären, wer jeden Tag welche Aufgabe übernimmt. Im Plan steht, wer das Meerschweinchen auch am Sonntag füttert.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: Der Plan klärt für jeden Tag die Zuständigkeit bei der Pflege.","ok": true},{"text": "Im Beispiel wird sichtbar: Beim Planen können wir uns einen Namen für das Tier überlegen.","ok": false},{"text": "Im Beispiel wird sichtbar: In einem Pflegeplan stehen mehrere Aufgaben und Kindernamen.","ok": false}]},{"text": "Wir sollten vor dem Tierkauf einen Pflegeplan machen, weil wir vorher klären, wer jeden Tag welche Aufgabe übernimmt. Neben dem Plan hängen drei Vorschläge für den Namen des Tieres.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten vor dem Tierkauf einen Pflegeplan machen, weil wir dabei überlegen, welchen Namen das Tier bekommt. Auf dem Pflegeplan klebt neben jedem Namen ein kleines Bild des Tieres.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:freizeit","meinung": "Wir sollten einen Nachmittag ohne feste Termine lassen. Ziel: Zeit für eigene Ideen finden.","optionen": [{"text": "Wir sollten einen Nachmittag ohne feste Termine lassen, weil wir selbst entscheiden können, was wir beginnen möchten. Ayla baute an ihrem freien Nachmittag aus Kartons ein eigenes Spiel.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: In freier Zeit können wir selbst ein eigenes Vorhaben beginnen.","ok": true},{"text": "Im Beispiel wird sichtbar: Für einen freien Nachmittag brauchen wir keine Kurstasche.","ok": false},{"text": "Im Beispiel wird sichtbar: Ein freier Nachmittag hat keinen festen Platz im Kursplan.","ok": false}]},{"text": "Wir sollten einen Nachmittag ohne feste Termine lassen, weil wir selbst entscheiden können, was wir beginnen möchten. Ayla stellte ihre unbenutzte Sporttasche an diesem Tag in den Schrank.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten einen Nachmittag ohne feste Termine lassen, weil wir dann keine Sporttasche für einen Kurs packen müssen. Ayla stellte ihre neue Pappschachtel nach dem Mittagessen auf den Schreibtisch.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:fahrrad","meinung": "Wir sollten Fahrräder vor dem Ausflug gemeinsam prüfen. Ziel: mit sicheren Fahrrädern losfahren.","optionen": [{"text": "Wir sollten Fahrräder vor dem Ausflug gemeinsam prüfen, weil wir defekte Bremsen noch vor der Abfahrt entdecken. Beim Bremsentest merkte Paul, dass seine hintere Bremse nicht greift.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: Beim Test fallen kaputte Bremsen schon vor der Abfahrt auf.","ok": true},{"text": "Im Beispiel wird sichtbar: Beim Treffen können wir die Fahrräder der anderen ansehen.","ok": false},{"text": "Im Beispiel wird sichtbar: Vor dem Ausflug stehen viele Fahrräder auf unserem Schulhof.","ok": false}]},{"text": "Wir sollten Fahrräder vor dem Ausflug gemeinsam prüfen, weil wir defekte Bremsen noch vor der Abfahrt entdecken. Beim Treffen verglich Paul seinen Lenker mit dem Fahrrad von Sara.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten Fahrräder vor dem Ausflug gemeinsam prüfen, weil wir dabei die verschiedenen Fahrräder der Klasse ansehen. Pauls Fahrrad hatte beim Treffen am Morgen einen blauen statt roten Sattel.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:schulweg","meinung": "Wir sollten für den Schulweg sichere Querungen auswählen. Ziel: gefahrlos über viel befahrene Straßen kommen.","optionen": [{"text": "Wir sollten für den Schulweg sichere Querungen auswählen, weil wir an übersichtlichen Stellen den Verkehr besser sehen. An der freien Kreuzung konnte Eda beide Fahrtrichtungen gut sehen.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: An freien Querungen können wir den Verkehr besser sehen.","ok": true},{"text": "Im Beispiel wird sichtbar: Auf dem gewählten Schulweg treffen wir andere Kinder häufiger.","ok": false},{"text": "Im Beispiel wird sichtbar: Auf unserem Schulweg müssen wir mehrere Straßen überqueren.","ok": false}]},{"text": "Wir sollten für den Schulweg sichere Querungen auswählen, weil wir an übersichtlichen Stellen den Verkehr besser sehen. An der Kreuzung traf Eda drei Kinder aus ihrer Parallelklasse.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten für den Schulweg sichere Querungen auswählen, weil wir auf diesem Weg andere Kinder öfter treffen. Auf dem Schulweg kam Eda an der Kreuzung an einem kleinen Laden vorbei.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:umwelt","meinung": "Wir sollten in leeren Klassenräumen das Licht ausschalten. Ziel: unnötigen Stromverbrauch vermeiden.","optionen": [{"text": "Wir sollten in leeren Klassenräumen das Licht ausschalten, weil leere Räume keine Beleuchtung zum Arbeiten brauchen. Während die Klasse beim Sport war, blieben die Lampen im Raum aus.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: Ohne Menschen im Raum ist keine Beleuchtung zum Arbeiten nötig.","ok": true},{"text": "Im Beispiel wird sichtbar: Das Ausschalten erinnert uns an das Ende der Arbeitsphase.","ok": false},{"text": "Im Beispiel wird sichtbar: An der Decke unserer Klassenräume hängen mehrere Lampen.","ok": false}]},{"text": "Wir sollten in leeren Klassenräumen das Licht ausschalten, weil leere Räume keine Beleuchtung zum Arbeiten brauchen. Nach dem Sport zählte Malik die Lampen über den Fenstern im Raum.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten in leeren Klassenräumen das Licht ausschalten, weil wir dadurch an das Ende der Pause erinnert werden. Malik entdeckte im Raum nach dem Sportunterricht ein neues Plakat an der Wand.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:muell","meinung": "Wir sollten Papier getrennt von Essensresten sammeln. Ziel: sauberes Papier wiederverwerten lassen.","optionen": [{"text": "Wir sollten Papier getrennt von Essensresten sammeln, weil Essensreste das gesammelte Papier nicht verschmutzen. Die alten Arbeitsblätter blieben ohne die Bananenschalen sauber.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: Ohne Essensreste wird das gesammelte Papier nicht schmutzig.","ok": true},{"text": "Im Beispiel wird sichtbar: Beim Trennen lernen wir unsere verschiedenen Abfalleimer kennen.","ok": false},{"text": "Im Beispiel wird sichtbar: Papier und Essensreste gehören in unterschiedliche Abfalleimer.","ok": false}]},{"text": "Wir sollten Papier getrennt von Essensresten sammeln, weil Essensreste das gesammelte Papier nicht verschmutzen. Neben dem Papiereimer stand ein kleiner brauner Eimer mit Deckel.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten Papier getrennt von Essensresten sammeln, weil wir dadurch unsere verschiedenen Abfalleimer kennenlernen. Der Papiereimer wurde am Freitag neben das Fenster des Klassenraums gestellt.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:ausflug","meinung": "Wir sollten Ausflugsziele mit dem Bus erreichen können. Ziel: allen Kindern die Teilnahme ermöglichen.","optionen": [{"text": "Wir sollten Ausflugsziele mit dem Bus erreichen können, weil niemand für die Anfahrt ein eigenes Auto braucht. Auch Nuri konnte mitfahren, obwohl seine Familie kein Auto hat.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: Im Bus kann man auch ohne eigenes Auto zum Ziel mitkommen.","ok": true},{"text": "Im Beispiel wird sichtbar: Bei der Busfahrt können wir die Landschaft unterwegs ansehen.","ok": false},{"text": "Im Beispiel wird sichtbar: Der Bus fährt an einer Haltestelle vor unserer Schule ab.","ok": false}]},{"text": "Wir sollten Ausflugsziele mit dem Bus erreichen können, weil niemand für die Anfahrt ein eigenes Auto braucht. Nuri entdeckte während der Fahrt einen Storch auf einer Wiese.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten Ausflugsziele mit dem Bus erreichen können, weil wir während der Fahrt die Landschaft anschauen können. Nuri fand auf dem Busfahrplan neben der Abfahrtszeit ein kleines Bussymbol.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:klassenfest","meinung": "Wir sollten für das Klassenfest verschiedene Aufgaben anbieten. Ziel: jedem Kind eine passende Beteiligung ermöglichen.","optionen": [{"text": "Wir sollten für das Klassenfest verschiedene Aufgaben anbieten, weil auch Kinder ohne Bühnenmut einen Beitrag leisten können. Luz wollte nicht auftreten und gestaltete stattdessen die Einladung.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: Auch ohne Bühnenmut können Kinder einen Beitrag leisten.","ok": true},{"text": "Im Beispiel wird sichtbar: Bei verschiedenen Aufgaben sammeln wir mehr Ideen für das Fest.","ok": false},{"text": "Im Beispiel wird sichtbar: Beim Klassenfest müssen mehrere Aufgaben gleichzeitig erledigt werden.","ok": false}]},{"text": "Wir sollten für das Klassenfest verschiedene Aufgaben anbieten, weil auch Kinder ohne Bühnenmut einen Beitrag leisten können. Luz legte die gestalteten Einladungen in einen großen bunten Karton.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten für das Klassenfest verschiedene Aufgaben anbieten, weil wir dadurch mehr verschiedene Dinge für das Fest sammeln. Die Einladung für das Klassenfest war auf beiden Seiten bunt bedruckt.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:gruppenarbeit","meinung": "Wir sollten in Gruppen klare Aufgaben absprechen. Ziel: doppelte Arbeit und vergessene Teile vermeiden.","optionen": [{"text": "Wir sollten in Gruppen klare Aufgaben absprechen, weil jeder weiß, welchen Teil der Aufgabe er übernimmt. Lara suchte Bilder, während Cem den Text schrieb; kein Teil fehlte.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: Durch Absprachen kennt jeder seinen eigenen Teil der Aufgabe.","ok": true},{"text": "Im Beispiel wird sichtbar: Bei der Absprache können wir mit neuen Partnern sprechen.","ok": false},{"text": "Im Beispiel wird sichtbar: In einer Arbeitsgruppe sitzen mehrere Kinder an einem Tisch.","ok": false}]},{"text": "Wir sollten in Gruppen klare Aufgaben absprechen, weil jeder weiß, welchen Teil der Aufgabe er übernimmt. Lara saß bei der Arbeit zum ersten Mal neben Cem am Fenstertisch.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten in Gruppen klare Aufgaben absprechen, weil wir dadurch öfter mit neuen Partnern sprechen können. Beim Gruppenplakat lagen der rote Kleber und die Schere neben Cems Heft.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:bibliothek","meinung": "Wir sollten Bücher in der Klassenbibliothek beschriften. Ziel: passende Bücher schneller finden.","optionen": [{"text": "Wir sollten Bücher in der Klassenbibliothek beschriften, weil wir am Schild sofort das Thema eines Regals erkennen. Unter dem Schild Tiergeschichten fand Kim sofort ein passendes Buch.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: Die Schilder zeigen sofort, welches Thema ein Regal enthält.","ok": true},{"text": "Im Beispiel wird sichtbar: Mit selbst gemalten Schildern können wir Bilder im Raum zeigen.","ok": false},{"text": "Im Beispiel wird sichtbar: Die Bücher unserer Klassenbibliothek stehen in mehreren Regalen.","ok": false}]},{"text": "Wir sollten Bücher in der Klassenbibliothek beschriften, weil wir am Schild sofort das Thema eines Regals erkennen. Kim malte für das neue Schild einen kleinen braunen Bären aufs Papier.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten Bücher in der Klassenbibliothek beschriften, weil wir unsere selbst gemalten Schilder im Raum zeigen können. Am Regal mit Tiergeschichten hingen zwei gleich große Schilder aus Pappe.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:schulessen","meinung": "Wir sollten beim Schulessen kleine erste Portionen wählen. Ziel: weniger gutes Essen wegwerfen.","optionen": [{"text": "Wir sollten beim Schulessen kleine erste Portionen wählen, weil wir erst nachnehmen, wenn wir noch Hunger haben. Sibel nahm wenig Reis, aß alles und holte bei Bedarf noch etwas.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: Beim Nachnehmen passt die Essensmenge besser zum Hunger.","ok": true},{"text": "Im Beispiel wird sichtbar: Mit kleinen Portionen können wir verschiedene Teller erproben.","ok": false},{"text": "Im Beispiel wird sichtbar: An der Ausgabe stehen für die Kinder mehrere Stapel Teller bereit.","ok": false}]},{"text": "Wir sollten beim Schulessen kleine erste Portionen wählen, weil wir erst nachnehmen, wenn wir noch Hunger haben. Sibel wählte an der Ausgabe einen kleinen grünen Teller aus dem Stapel.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten beim Schulessen kleine erste Portionen wählen, weil wir dadurch verschiedene Tellergrößen ausprobieren können. Sibel bekam ihren Reis in der Mensa mit einem großen metallenen Löffel.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:trinken","meinung": "Wir sollten Wasserflaschen im Klassenraum auffüllen können. Ziel: beim Lernen genug Wasser trinken.","optionen": [{"text": "Wir sollten Wasserflaschen im Klassenraum auffüllen können, weil leere Flaschen auch während des Schultags wieder gefüllt werden. Nach dem Sport füllte Ravi seine leere Flasche auf und trank daraus.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: An der Füllstelle werden leere Flaschen wieder gefüllt.","ok": true},{"text": "Im Beispiel wird sichtbar: Mit eigenen Flaschen müssen wir keine fremden Becher benutzen.","ok": false},{"text": "Im Beispiel wird sichtbar: Unsere Trinkflaschen haben verschiedene Größen und Farben.","ok": false}]},{"text": "Wir sollten Wasserflaschen im Klassenraum auffüllen können, weil leere Flaschen auch während des Schultags wieder gefüllt werden. Ravi erkannte seine Flasche an einem selbst gemalten gelben Stern.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten Wasserflaschen im Klassenraum auffüllen können, weil wir unsere Flaschen nicht mit anderen verwechseln müssen. Der Hahn zum Füllen der Flaschen befindet sich neben der Tür zum Flur.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:lesezeit","meinung": "Wir sollten eine kurze stille Lesezeit einführen. Ziel: ohne Unterbrechung in Geschichten eintauchen.","optionen": [{"text": "Wir sollten eine kurze stille Lesezeit einführen, weil alle gleichzeitig lesen und niemand dazwischen spricht. Zehn stille Minuten lang konnte Maja einem Kapitel bis zum Ende folgen.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: Wenn alle still lesen, spricht niemand in die Geschichte hinein.","ok": true},{"text": "Im Beispiel wird sichtbar: In der Lesezeit können wir unsere Lieblingsbücher zeigen.","ok": false},{"text": "Im Beispiel wird sichtbar: In der Lesezeit liegen viele Bücher auf den Tischen im Raum.","ok": false}]},{"text": "Wir sollten eine kurze stille Lesezeit einführen, weil alle gleichzeitig lesen und niemand dazwischen spricht. Maja legte ihr Lieblingsbuch mit dem bunten Umschlag auf den Tisch.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten eine kurze stille Lesezeit einführen, weil wir dabei unsere mitgebrachten Lieblingsbücher zeigen können. Auf dem Regalbrett für die Lesezeit standen drei Bücher mit grünen Umschlägen.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:partnerwahl","meinung": "Wir sollten bei kurzen Partneraufgaben gelegentlich auslosen. Ziel: mit verschiedenen Kindern zusammenarbeiten lernen.","optionen": [{"text": "Wir sollten bei kurzen Partneraufgaben gelegentlich auslosen, weil wir auch mit Kindern außerhalb des Freundeskreises üben. Toni und Esma losten sich zum ersten Mal zusammen und teilten Ideen.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: Durch Lose üben wir auch mit Kindern außerhalb unserer Freunde.","ok": true},{"text": "Im Beispiel wird sichtbar: Beim Losen können wir unsere eigenen Namenskärtchen nutzen.","ok": false},{"text": "Im Beispiel wird sichtbar: Bei einer Partneraufgabe arbeiten jeweils zwei Kinder zusammen.","ok": false}]},{"text": "Wir sollten bei kurzen Partneraufgaben gelegentlich auslosen, weil wir auch mit Kindern außerhalb des Freundeskreises üben. Toni zog Esmas Namen von einer kleinen Karte mit blauem Rand.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten bei kurzen Partneraufgaben gelegentlich auslosen, weil wir durch das Losen unsere Namenskärtchen nutzen können. Die Namenskärtchen für die Partnerwahl lagen in einem kleinen Stoffbeutel.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:ordnung","meinung": "Wir sollten gemeinsam benutztes Material fest einsortieren. Ziel: benötigte Sachen ohne langes Suchen finden.","optionen": [{"text": "Wir sollten gemeinsam benutztes Material fest einsortieren, weil jeder den gleichen Platz für Schere und Kleber kennt. Zoe griff ins beschriftete Fach und fand sofort eine freie Schere.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: Ein fester Platz zeigt allen, wo Schere und Kleber liegen.","ok": true},{"text": "Im Beispiel wird sichtbar: Beim Einsortieren können wir unsere Materialkisten bemalen.","ok": false},{"text": "Im Beispiel wird sichtbar: Scheren und Kleber gehören gemeinsam zu unserem Bastelmaterial.","ok": false}]},{"text": "Wir sollten gemeinsam benutztes Material fest einsortieren, weil jeder den gleichen Platz für Schere und Kleber kennt. Zoe bemalte die Kiste am selben Tag mit roten und grünen Punkten.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten gemeinsam benutztes Material fest einsortieren, weil wir dabei unsere Materialkisten neu bemalen können. In Zoes Materialkiste lagen drei große Scheren mit abgerundeten Spitzen.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:spielregeln","meinung": "Wir sollten Spielregeln vor dem Turnier gemeinsam klären. Ziel: Streit über unklare Entscheidungen vermeiden.","optionen": [{"text": "Wir sollten Spielregeln vor dem Turnier gemeinsam klären, weil wir schon vor dem Spiel wissen, welche Regeln gelten. Als der Ball die Linie berührte, kannten beide Teams die vereinbarte Regel.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: Nach dem Klären wissen beide Teams, welche Regeln gelten.","ok": true},{"text": "Im Beispiel wird sichtbar: Vor dem Turnier erfahren wir die Namen der Mannschaften.","ok": false},{"text": "Im Beispiel wird sichtbar: Bei einem Turnier spielen mehrere Mannschaften gegeneinander.","ok": false}]},{"text": "Wir sollten Spielregeln vor dem Turnier gemeinsam klären, weil wir schon vor dem Spiel wissen, welche Regeln gelten. Vor dem Anpfiff nannte jedes Team seinen selbst gewählten Namen.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten Spielregeln vor dem Turnier gemeinsam klären, weil wir dabei die Namen der anderen Mannschaften erfahren. Die vereinbarten Turnierregeln standen auf einem Plakat neben der Hallentür.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:radstaender","meinung": "Wir sollten Fahrräder an festen Plätzen abstellen. Ziel: den Eingang zur Schule frei halten.","optionen": [{"text": "Wir sollten Fahrräder an festen Plätzen abstellen, weil kein Rad mitten im Weg vor der Eingangstür steht. Als alle Räder im Ständer standen, kam eine Kindergruppe durch die Tür.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: Mit festen Plätzen steht kein Rad vor unserer Eingangstür.","ok": true},{"text": "Im Beispiel wird sichtbar: Bei festen Plätzen finden wir die Räder unserer Freunde leichter.","ok": false},{"text": "Im Beispiel wird sichtbar: Die Fahrradständer unserer Schule stehen neben dem Eingang.","ok": false}]},{"text": "Wir sollten Fahrräder an festen Plätzen abstellen, weil kein Rad mitten im Weg vor der Eingangstür steht. Amin erkannte im Ständer das rote Fahrrad seiner besten Freundin.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten Fahrräder an festen Plätzen abstellen, weil wir dort die Fahrräder unserer Freunde wiederfinden können. Amins Rad stand nach der Schule zwischen zwei größeren schwarzen Fahrrädern.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:tauschregal","meinung": "Wir sollten ein Tauschregal für brauchbare Schulsachen aufstellen. Ziel: gut erhaltene Dinge länger nutzen.","optionen": [{"text": "Wir sollten ein Tauschregal für brauchbare Schulsachen aufstellen, weil andere Kinder noch verwendbare Sachen weiterbenutzen können. Eine noch volle Packung Buntstifte wurde von einem anderen Kind genutzt.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: Im Regal können andere die noch guten Sachen weiterbenutzen.","ok": true},{"text": "Im Beispiel wird sichtbar: Beim Tauschen entdecken wir verschiedene Farben und Muster.","ok": false},{"text": "Im Beispiel wird sichtbar: In einem Tauschregal liegen verschiedene Sachen zum Mitnehmen.","ok": false}]},{"text": "Wir sollten ein Tauschregal für brauchbare Schulsachen aufstellen, weil andere Kinder noch verwendbare Sachen weiterbenutzen können. Neben der Packung Buntstifte lag ein Heft mit einem bunten Tierbild.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten ein Tauschregal für brauchbare Schulsachen aufstellen, weil wir dabei verschiedene Farben und Muster entdecken. Das Tauschregal hatte vier Fächer und stand in unserem Flur neben der Tür.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]},
    {"id": "STAERKER_BELEGT:lernpause","meinung": "Wir sollten bei langen Arbeitsphasen kurze Bewegungspausen machen. Ziel: nach langem Sitzen wieder aufmerksam arbeiten.","optionen": [{"text": "Wir sollten bei langen Arbeitsphasen kurze Bewegungspausen machen, weil wir die sitzende Haltung kurz unterbrechen können. Nach dem Strecken konnte Luis der nächsten Erklärung wieder folgen.","ok": true,"info": "Das Beispiel macht genau den genannten Nutzen sichtbar.","warum": [{"text": "Im Beispiel wird sichtbar: In Bewegungspausen unterbrechen wir das lange Sitzen.","ok": true},{"text": "Im Beispiel wird sichtbar: In der Pause können wir unsere gewählten Bewegungen zeigen.","ok": false},{"text": "Im Beispiel wird sichtbar: Eine Bewegungspause unterbricht unsere lange Arbeitsphase.","ok": false}]},{"text": "Wir sollten bei langen Arbeitsphasen kurze Bewegungspausen machen, weil wir die sitzende Haltung kurz unterbrechen können. Luis zeigte der Klasse in der Pause seine neue Balanceübung am Platz.","ok": false,"info": "Das Beispiel beschreibt ein anderes Detail des Vorhabens."},{"text": "Wir sollten bei langen Arbeitsphasen kurze Bewegungspausen machen, weil wir dabei unsere selbst gewählten Bewegungen zeigen können. Das Zeichen für die Bewegungspause hing als gemalte Karte neben der Tafel.","ok": false,"info": "Das Beispiel ersetzt die Meinung durch einen neuen Wunsch."}]}
