    {"id": "GEGEN_BELEGT:pausenecke","argument": "Wir sollten eine ruhige Pausenecke einrichten, weil wir dort abschalten und neue Kraft sammeln. Beobachtung: Nach zehn ruhigen Minuten konnte Mila wieder ihrer Aufgabe folgen.","optionen": [{"text": "Für Ballspiele bleibt dann weniger Platz auf dem Hof.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Wer sich ausruht, muss nicht die ganze Pause auf Lärm achten.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "In der Ecke können wir Karten mit unseren Freunden tauschen.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:hausaufgaben","argument": "Wir sollten Hausaufgaben am Ende gemeinsam notieren, weil wir die Einträge noch mit der Tafel vergleichen. Beobachtung: Omar bemerkte beim Vergleich die fehlende zweite Matheaufgabe.","optionen": [{"text": "Das gemeinsame Notieren kostet Zeit am Stundenende.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Ein gemeinsamer Blick zeigt, ob eine Aufgabe im Eintrag fehlt.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "Beim Notieren können wir unsere Hefte ordentlich gestalten.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:schulbeginn","argument": "Wir sollten eine Woche lang später mit der Schule beginnen, weil wir unsere Müdigkeit vor und nach dem Versuch vergleichen. Beobachtung: Nora notierte jeden Morgen, wie wach sie in der ersten Stunde war.","optionen": [{"text": "Unser Schulbus fährt nur zu den bisherigen Zeiten.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Ein Vergleich beider Wochen zeigt Unterschiede in der Müdigkeit.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "Vor dem späteren Beginn können wir gemeinsam frühstücken.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:sitzordnung","argument": "Wir sollten einen freien Blick auf die Tafel ermöglichen, weil keiner beim Lesen um andere herumsehen muss. Beobachtung: Lina konnte die Rechnung nach dem Umstellen ohne Aufstehen lesen.","optionen": [{"text": "Beim Umstellen könnten die Laufwege zu schmal werden.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Ein freies Sichtfeld hilft auch den Kindern in der letzten Reihe.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "Nach dem Umstellen können wir unsere Freunde leichter sehen.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:klassenregel","argument": "Wir sollten eine feste Reihenfolge beim Sprechen nutzen, weil jeder reden kann, ohne von anderen übertönt zu werden. Beobachtung: Als Amira an der Reihe war, hörten alle ihren Vorschlag bis zum Ende.","optionen": [{"text": "Manchmal will jemand sofort eine wichtige Frage stellen.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Wer auf seinen Einsatz wartet, überdeckt die leise Stimme nicht.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "Vor dem Sprechen können wir unsere Beiträge aufschreiben.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:dienste","argument": "Wir sollten die Klassendienste jede Woche wechseln, weil nicht jede Woche dieselben Kinder alles erledigen. Beobachtung: Diese Woche fegt Ben, nächste Woche übernimmt Elif seinen Dienst.","optionen": [{"text": "Neue Kinder wissen oft noch nicht, wie ein Dienst geht.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Auch unbeliebte Dienste werden beim Wechsel von allen übernommen.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "Durch den Wechsel lernen wir unterschiedliche Dienste kennen.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:klassenfahrt","argument": "Wir sollten bei der Klassenfahrt gemeinsame Aufgaben planen, weil wir beim Lösen einer Aufgabe aufeinander angewiesen sind. Beobachtung: Bei der Wegsuche erklärten sich zwei sonst fremde Kinder ihre Ideen.","optionen": [{"text": "Bei einem Wettbewerb können schwächere Kinder ausgeschlossen werden.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Bei gemeinsamen Aufgaben hört man auch die Ideen neuer Partner.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "Auf der Fahrt können wir die Wege um die Unterkunft erkunden.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:schulhof","argument": "Wir sollten Spielgeräte in der Pause ausleihen können, weil auch Kinder ohne eigenes Gerät etwas ausprobieren können. Beobachtung: Ivo hatte kein Springseil dabei und konnte sich eines ausleihen.","optionen": [{"text": "Manche Geräte werden vielleicht nicht wieder zurückgebracht.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Fehlende eigene Spielsachen schließen dann niemanden vom Spiel aus.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "Bei der Ausgabe lernen wir die Namen anderer Kinder kennen.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:sport","argument": "Wir sollten im Sport verschiedene Spielarten ausprobieren, weil nicht in jedem Spiel dieselben Fähigkeiten zählen. Beobachtung: Beim Zielwerfen war Sam stark, beim Laufspiel half Mara dem Team.","optionen": [{"text": "Bei ständig neuen Spielen geht viel Zeit fürs Erklären verloren.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Wer langsam läuft, kann bei einer anderen Aufgabe trotzdem helfen.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "Durch neue Spiele lernen wir verschiedene Spielnamen kennen.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:ags","argument": "Wir sollten vor der AG-Wahl Schnupperstunden anbieten, weil wir vor der Wahl die Tätigkeit selbst ausprobieren. Beobachtung: Nach dem Bauen eines Modells wusste Deniz, dass die Werk-AG passt.","optionen": [{"text": "Für mehrere Schnupperstunden fehlt uns die freie Zeit.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Ein eigener Versuch zeigt besser als ein Name, was man gern macht.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "Beim Schnuppern lernen wir Kinder aus anderen Klassen kennen.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:handys","argument": "Wir sollten Handys während der Gruppenarbeit weglegen, weil keine Nachricht mitten im Gespräch unsere Aufmerksamkeit ablenkt. Beobachtung: Ohne Nachrichtenton hörte Jona den Vorschlag seiner Partnerin zu Ende.","optionen": [{"text": "Für manche Aufgaben brauchen wir das Handy zum Nachschlagen.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Ohne Blick aufs Display bemerkt man Fragen der anderen schneller.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "In der Tasche können die Geräte nicht vom Gruppentisch fallen.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:haustiere","argument": "Wir sollten vor dem Tierkauf einen Pflegeplan machen, weil wir vorher klären, wer jeden Tag welche Aufgabe übernimmt. Beobachtung: Im Plan steht, wer das Meerschweinchen auch am Sonntag füttert.","optionen": [{"text": "In den Ferien ist vielleicht die ganze Familie unterwegs.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Feste Zuständigkeiten helfen auch am Wochenende gegen vergessene Pflege.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "Beim Planen können wir uns einen Namen für das Tier überlegen.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:freizeit","argument": "Wir sollten einen Nachmittag ohne feste Termine lassen, weil wir selbst entscheiden können, was wir beginnen möchten. Beobachtung: Ayla baute an ihrem freien Nachmittag aus Kartons ein eigenes Spiel.","optionen": [{"text": "Ein fester freier Nachmittag könnte mit einem beliebten Kurs zusammenfallen.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Ohne fertigen Kursplan entsteht Raum für selbst gewählte Vorhaben.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "Für einen freien Nachmittag brauchen wir keine Kurstasche.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:fahrrad","argument": "Wir sollten Fahrräder vor dem Ausflug gemeinsam prüfen, weil wir defekte Bremsen noch vor der Abfahrt entdecken. Beobachtung: Beim Bremsentest merkte Paul, dass seine hintere Bremse nicht greift.","optionen": [{"text": "Nicht alle Kinder können eine kaputte Bremse reparieren.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Ein vorher entdeckter Fehler kann noch vor der Fahrt behoben werden.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "Beim Treffen können wir die Fahrräder der anderen ansehen.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:schulweg","argument": "Wir sollten für den Schulweg sichere Querungen auswählen, weil wir an übersichtlichen Stellen den Verkehr besser sehen. Beobachtung: An der freien Kreuzung konnte Eda beide Fahrtrichtungen gut sehen.","optionen": [{"text": "Der Weg zur übersichtlichen Querung ist etwas länger.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Gute Sicht lässt mehr Zeit, ein herannahendes Auto zu bemerken.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "Auf dem gewählten Schulweg treffen wir andere Kinder häufiger.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:umwelt","argument": "Wir sollten in leeren Klassenräumen das Licht ausschalten, weil leere Räume keine Beleuchtung zum Arbeiten brauchen. Beobachtung: Während die Klasse beim Sport war, blieben die Lampen im Raum aus.","optionen": [{"text": "Das letzte Kind vergisst das Ausschalten vielleicht im Alltag.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Eine ausgeschaltete Lampe verbraucht in dieser Zeit keinen Strom.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "Das Ausschalten erinnert uns an das Ende der Arbeitsphase.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:muell","argument": "Wir sollten Papier getrennt von Essensresten sammeln, weil Essensreste das gesammelte Papier nicht verschmutzen. Beobachtung: Die alten Arbeitsblätter blieben ohne die Bananenschalen sauber.","optionen": [{"text": "Manche Kinder wissen nicht, welcher Abfall wohin gehört.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Sauberes Altpapier lässt sich besser für neue Papierwaren nutzen.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "Beim Trennen lernen wir unsere verschiedenen Abfalleimer kennen.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:ausflug","argument": "Wir sollten Ausflugsziele mit dem Bus erreichen können, weil niemand für die Anfahrt ein eigenes Auto braucht. Beobachtung: Auch Nuri konnte mitfahren, obwohl seine Familie kein Auto hat.","optionen": [{"text": "Die Busfahrt macht den Ausflug für Familien teurer.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Eine gemeinsame Anfahrt hängt nicht vom Auto der Eltern ab.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "Bei der Busfahrt können wir die Landschaft unterwegs ansehen.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:klassenfest","argument": "Wir sollten für das Klassenfest verschiedene Aufgaben anbieten, weil auch Kinder ohne Bühnenmut einen Beitrag leisten können. Beobachtung: Luz wollte nicht auftreten und gestaltete stattdessen die Einladung.","optionen": [{"text": "Beliebte Aufgaben werden vielleicht von zu vielen Kindern gewählt.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Wer nicht vor allen sprechen will, hilft trotzdem bei der Vorbereitung.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "Bei verschiedenen Aufgaben sammeln wir mehr Ideen für das Fest.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:gruppenarbeit","argument": "Wir sollten in Gruppen klare Aufgaben absprechen, weil jeder weiß, welchen Teil der Aufgabe er übernimmt. Beobachtung: Lara suchte Bilder, während Cem den Text schrieb; kein Teil fehlte.","optionen": [{"text": "Eine Aufgabe kann für ein Kind zu schwer sein.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Klare Zuständigkeiten zeigen, welcher Teil noch nicht bearbeitet ist.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "Bei der Absprache können wir mit neuen Partnern sprechen.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:bibliothek","argument": "Wir sollten Bücher in der Klassenbibliothek beschriften, weil wir am Schild sofort das Thema eines Regals erkennen. Beobachtung: Unter dem Schild Tiergeschichten fand Kim sofort ein passendes Buch.","optionen": [{"text": "Zu viele kleine Gruppen können die Suche unübersichtlich machen.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Wer ein Thema sucht, muss dann nicht jedes Buch einzeln herausziehen.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "Mit selbst gemalten Schildern können wir Bilder im Raum zeigen.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:schulessen","argument": "Wir sollten beim Schulessen kleine erste Portionen wählen, weil wir erst nachnehmen, wenn wir noch Hunger haben. Beobachtung: Sibel nahm wenig Reis, aß alles und holte bei Bedarf noch etwas.","optionen": [{"text": "Langes Anstehen zum Nachholen könnte die Essenszeit verkürzen.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Auf dem Teller bleibt weniger zurück, wenn die Menge zum Hunger passt.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "Mit kleinen Portionen können wir verschiedene Teller erproben.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:trinken","argument": "Wir sollten Wasserflaschen im Klassenraum auffüllen können, weil leere Flaschen auch während des Schultags wieder gefüllt werden. Beobachtung: Nach dem Sport füllte Ravi seine leere Flasche auf und trank daraus.","optionen": [{"text": "Am Wasserhahn könnte mitten im Unterricht eine Schlange entstehen.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Eine erreichbare Füllstelle hilft auch nach einer vergessenen Füllung.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "Mit eigenen Flaschen müssen wir keine fremden Becher benutzen.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:lesezeit","argument": "Wir sollten eine kurze stille Lesezeit einführen, weil alle gleichzeitig lesen und niemand dazwischen spricht. Beobachtung: Zehn stille Minuten lang konnte Maja einem Kapitel bis zum Ende folgen.","optionen": [{"text": "Einige Kinder brauchen beim Lesen einzelner Wörter Unterstützung.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Stille hilft, den Zusammenhang zwischen mehreren Seiten zu behalten.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "In der Lesezeit können wir unsere Lieblingsbücher zeigen.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:partnerwahl","argument": "Wir sollten bei kurzen Partneraufgaben gelegentlich auslosen, weil wir auch mit Kindern außerhalb des Freundeskreises üben. Beobachtung: Toni und Esma losten sich zum ersten Mal zusammen und teilten Ideen.","optionen": [{"text": "Ein zugelostes Paar könnte bei einer Aufgabe gar nicht weiterkommen.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Neue Partner zeigen, wie andere Kinder an dieselbe Aufgabe herangehen.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "Beim Losen können wir unsere eigenen Namenskärtchen nutzen.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:ordnung","argument": "Wir sollten gemeinsam benutztes Material fest einsortieren, weil jeder den gleichen Platz für Schere und Kleber kennt. Beobachtung: Zoe griff ins beschriftete Fach und fand sofort eine freie Schere.","optionen": [{"text": "Beim schnellen Aufräumen könnte Material im falschen Fach landen.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Ein fester Platz hilft auch Kindern, die das Material nicht weggeräumt haben.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "Beim Einsortieren können wir unsere Materialkisten bemalen.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:spielregeln","argument": "Wir sollten Spielregeln vor dem Turnier gemeinsam klären, weil wir schon vor dem Spiel wissen, welche Regeln gelten. Beobachtung: Als der Ball die Linie berührte, kannten beide Teams die vereinbarte Regel.","optionen": [{"text": "Bis wir uns geeinigt haben, bleibt weniger Zeit zum Spielen.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Eine bekannte Regel bietet beiden Seiten dieselbe Grundlage bei Streit.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "Vor dem Turnier erfahren wir die Namen der Mannschaften.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:radstaender","argument": "Wir sollten Fahrräder an festen Plätzen abstellen, weil kein Rad mitten im Weg vor der Eingangstür steht. Beobachtung: Als alle Räder im Ständer standen, kam eine Kindergruppe durch die Tür.","optionen": [{"text": "Die vorhandenen Ständer reichen nicht für alle Fahrräder aus.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Ein freier Eingang lässt auch mit einer großen Tasche genug Durchgang.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "Bei festen Plätzen finden wir die Räder unserer Freunde leichter.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:tauschregal","argument": "Wir sollten ein Tauschregal für brauchbare Schulsachen aufstellen, weil andere Kinder noch verwendbare Sachen weiterbenutzen können. Beobachtung: Eine noch volle Packung Buntstifte wurde von einem anderen Kind genutzt.","optionen": [{"text": "Im Regal könnten kaputte oder unbrauchbare Sachen landen.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Was weiterverwendet wird, muss nicht gleich neu gekauft werden.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "Beim Tauschen entdecken wir verschiedene Farben und Muster.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]},
    {"id": "GEGEN_BELEGT:lernpause","argument": "Wir sollten bei langen Arbeitsphasen kurze Bewegungspausen machen, weil wir die sitzende Haltung kurz unterbrechen können. Beobachtung: Nach dem Strecken konnte Luis der nächsten Erklärung wieder folgen.","optionen": [{"text": "Nach einer Pause finden manche Kinder schwer zurück zur Aufgabe.","ok": true,"info": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","warum": [{"text": "Der Satz nennt einen Nachteil des vorgeschlagenen Plans.","ok": true},{"text": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans.","ok": false},{"text": "Der Satz erklärt ein Detail bei der Umsetzung des Plans.","ok": false}]},{"text": "Ein kurzer Wechsel der Haltung erleichtert einen neuen Arbeitsbeginn.","ok": false,"info": "Der Satz nennt einen weiteren Vorteil des vorgeschlagenen Plans."},{"text": "In der Pause können wir unsere gewählten Bewegungen zeigen.","ok": false,"info": "Der Satz erklärt ein Detail bei der Umsetzung des Plans."}]}
